const e=JSON.parse(`[{"id":"adverbial","kind":"conjugation","tier":"morphological","labelJa":"～く","labelEn":"adjective as adverb","jlpt":"N5","gloss":null,"exampleJa":"毎朝、早く起きる。","exampleEn":"I get up early every morning.","category":"form"},{"id":"advice-hou","kind":"pattern","tier":"lexical","labelJa":"～たほうがいい","labelEn":"you'd better do it (or better not)","jlpt":"N4","gloss":"gives advice; attaches to a past (た) or negative (ない) verb — 'you'd better (not) do X'","exampleJa":"早く寝たほうがいい。","exampleEn":"You'd better go to bed early."},{"id":"ageku","kind":"pattern","tier":"lexical","labelJa":"～あげく","labelEn":"after all that, it ended badly","jlpt":"N2","gloss":"after a prolonged effort or trouble, it ended in a (usually bad) result","exampleJa":"さんざん悩んだあげく、やめることにした。","exampleEn":"After agonizing over it, I ended up quitting."},{"id":"aida-ni","kind":"pattern","tier":"lexical","labelJa":"～間に","labelEn":"something happens during a span of time","jlpt":"N3","gloss":"'at some point during the span of X' — something happens within that interval (寝ている間に)","exampleJa":"赤ちゃんが寝ている間に家事をする。","exampleEn":"I do the housework while the baby is sleeping."},{"id":"amari","kind":"pattern","tier":"lexical","labelJa":"～のあまり","labelEn":"so much that","jlpt":"N2","gloss":"'out of (an excess of) X' — an extreme emotion/state causing the result","exampleJa":"嬉しさのあまり泣いた。","exampleEn":"I cried out of sheer joy."},{"id":"amari-ni","kind":"pattern","tier":"lexical","labelJa":"あまりに（も）","labelEn":"so much ... that (an extreme degree)","jlpt":"N2","gloss":"the degree is so extreme that the following result ensues","exampleJa":"彼の話があまりにも面白くて、笑ってしまった。","exampleEn":"His story was so funny that I burst out laughing."},{"id":"amari-no","kind":"pattern","tier":"lexical","labelJa":"あまりの～に","labelEn":"the sheer ... made it happen","jlpt":"N2","gloss":"prenominal form: the sheer extent of the noun causes the result","exampleJa":"あまりの忙しさに、食事をする時間もなかった。","exampleEn":"I was so busy that I had no time even to eat."},{"id":"ato-de","kind":"pattern","tier":"lexical","labelJa":"～後で","labelEn":"\\"after\\" doing something","jlpt":"N3","gloss":"marks the temporal 'after' (V-た後で / N の後で)","exampleJa":"食べた後で散歩した。","exampleEn":"I took a walk after eating."},{"id":"ba-hodo","kind":"pattern","tier":"lexical","labelJa":"～ば～ほど","labelEn":"the more ..., the more ...","jlpt":"N3","gloss":"repeating the verb/adjective in ば-form then plain form before ほど scales the result","exampleJa":"練習すればするほど上手になる。","exampleEn":"The more you practice, the better you get."},{"id":"bakari","kind":"pattern","tier":"lexical","labelJa":"～ばかり","labelEn":"just did / nothing but","jlpt":"N4","gloss":"indicates exclusive focus or a just-completed action depending on form","exampleJa":"今着いたばかりです。","exampleEn":"I just arrived."},{"id":"bakari-de-naku","kind":"pattern","tier":"lexical","labelJa":"～ばかりでなく","labelEn":"not only X, but also Y","jlpt":"N3","gloss":"extends a statement beyond the obvious case","exampleJa":"勉強ばかりでなく、運動もする。","exampleEn":"I not only study but also exercise."},{"id":"bakari-ni","kind":"pattern","tier":"lexical","labelJa":"～ばかりに","labelEn":"simply because of that one thing","jlpt":"N2","gloss":"cites a single cause leading to an undesirable consequence","exampleJa":"お金がないばかりに旅行に行けない。","exampleEn":"Just because I have no money, I can't travel."},{"id":"beki","kind":"pattern","tier":"lexical","labelJa":"～べき","labelEn":"should / ought to","jlpt":"N3","gloss":"expresses a strong recommendation or moral obligation; attaches to the dictionary form (する→すべき)","exampleJa":"約束は守るべきだ。","exampleEn":"You should keep your promises."},{"id":"beku","kind":"pattern","tier":"lexical","labelJa":"～べく","labelEn":"in order to (formal)","jlpt":"N1","gloss":"literary purpose form of べし: did the action so as to achieve the goal","exampleJa":"真相を究明すべく、調査委員会が設置された。","exampleEn":"A committee was set up in order to uncover the truth."},{"id":"causative","kind":"conjugation","tier":"morphological","labelJa":"～（さ）せる","labelEn":"make or let someone do","jlpt":"N4","gloss":null,"exampleJa":"母は子供に野菜を食べさせた。","exampleEn":"The mother made the child eat vegetables.","category":"voice"},{"id":"causative-passive","kind":"conjugation","tier":"morphological","labelJa":"～（さ）せられる","labelEn":"be made to do","jlpt":"N4","gloss":null,"exampleJa":"子供のとき、母に野菜を食べさせられた。","exampleEn":"When I was a child, my mother made me eat vegetables.","category":"voice"},{"id":"causative-su","kind":"conjugation","tier":"morphological","labelJa":"～（さ）す","labelEn":"short causative, casual make / let","jlpt":"N4","gloss":null,"exampleJa":"弟を買い物に行かした。","exampleEn":"I made my little brother go shopping.","category":"voice"},{"id":"conditional","kind":"pattern","tier":"morphological","labelJa":"～ば／～たら","labelEn":"saying \\"if\\" or \\"when\\"","jlpt":"N4","gloss":"provisional/temporal conditional: the 仮定形 + ば or the た-conditional たら — 'if/when X, then ...'","exampleJa":"安ければ買う。","exampleEn":"If it's cheap, I'll buy it."},{"id":"dakara","kind":"pattern","tier":"lexical","labelJa":"～だから","labelEn":"so / therefore","jlpt":"N4","gloss":"marks a reason that leads to the following statement","exampleJa":"雨だから、傘を持って行く。","exampleEn":"It's raining, so I'll take an umbrella."},{"id":"dake","kind":"pattern","tier":"lexical","labelJa":"～だけ","labelEn":"only / just","jlpt":"N5","gloss":"marks a limit or restriction on quantity, scope, or extent","exampleJa":"一つだけください。","exampleEn":"Please give me just one."},{"id":"dake-de-naku","kind":"pattern","tier":"lexical","labelJa":"～だけでなく","labelEn":"not only X, but also Y","jlpt":"N3","gloss":"extends a statement beyond the obvious case (synonym of ばかりでなく)","exampleJa":"彼は頭がいいだけでなく、優しい。","exampleEn":"He's not only smart but also kind."},{"id":"darake","kind":"pattern","tier":"morphological","labelJa":"～だらけ","labelEn":"covered in / full of something undesirable","jlpt":"N2","gloss":"'covered all over with / riddled with' something undesirable (泥だらけ, 間違いだらけ)","exampleJa":"服が泥だらけになった。","exampleEn":"My clothes got covered in mud."},{"id":"dasu","kind":"pattern","tier":"morphological","labelJa":"～出す","labelEn":"suddenly start to","jlpt":"N3","gloss":"an action begins suddenly or unexpectedly (泣き出す, 降り出す)","exampleJa":"赤ちゃんが急に泣き出した。","exampleEn":"The baby suddenly started crying."},{"id":"desho","kind":"pattern","tier":"morphological","labelJa":"～でしょう","labelEn":"probably (polite conjecture)","jlpt":"N5","gloss":"polite conjectural copula expressing probability or seeking soft agreement","exampleJa":"明日は雨でしょう。","exampleEn":"It will probably rain tomorrow."},{"id":"desu-nai","kind":"pattern","tier":"morphological","labelJa":"～ないです","labelEn":"polite negative with desu","jlpt":"N5","gloss":"adds です to a plain negative verb or adjective for casual politeness","exampleJa":"今日は行かないです。","exampleEn":"I'm not going today."},{"id":"dokoro-dewanai","kind":"pattern","tier":"lexical","labelJa":"～どころではない","labelEn":"this is no time for ...","jlpt":"N2","gloss":"strongly denies that the situation allows X: 'this is no time for X'","exampleJa":"今は旅行どころではない。","exampleEn":"This is no time for traveling."},{"id":"dokoroka","kind":"pattern","tier":"lexical","labelJa":"～どころか","labelEn":"far from / let alone","jlpt":"N3","gloss":"contradicts an expectation: 'far from X, actually Y' / 'let alone'","exampleJa":"安いどころか高い。","exampleEn":"Far from being cheap, it's expensive."},{"id":"furi-wo-suru","kind":"pattern","tier":"lexical","labelJa":"～ふりをする","labelEn":"pretending to do or be something","jlpt":"N3","gloss":"'pretend / act as if' — putting on an appearance that isn't real","exampleJa":"聞こえないふりをした。","exampleEn":"I pretended not to hear."},{"id":"ga-but","kind":"pattern","tier":"lexical","labelJa":"～が","labelEn":"but / however","jlpt":"N5","gloss":"conjunctive が joining two clauses with contrast (or as a soft connector)","exampleJa":"駅まで走ったが、間に合わなかった。","exampleEn":"I ran to the station, but didn't make it."},{"id":"ga-hayai-ka","kind":"pattern","tier":"lexical","labelJa":"～が早いか","labelEn":"no sooner than","jlpt":"N1","gloss":"the two actions are nearly simultaneous (literary)","exampleJa":"彼は財布を見つけるが早いか、駆け出した。","exampleEn":"No sooner had he spotted the wallet than he dashed off."},{"id":"gachi","kind":"pattern","tier":"morphological","labelJa":"～がち","labelEn":"tends to (usually something negative)","jlpt":"N3","gloss":"attaches to masu-stem or noun to mark a frequent, usually undesirable tendency","exampleJa":"最近、忘れがちなんです。","exampleEn":"Lately I tend to forget things."},{"id":"gai","kind":"pattern","tier":"morphological","labelJa":"～がい","labelEn":"worth doing","jlpt":"N2","gloss":"attaches to masu-stem to form a noun meaning worth or rewarding value of doing","exampleJa":"この仕事はやりがいがある。","exampleEn":"This job is rewarding."},{"id":"garu","kind":"pattern","tier":"morphological","labelJa":"～がる","labelEn":"show signs of feeling","jlpt":"N3","gloss":"expresses an externally observed third-person emotion or sensation","exampleJa":"弟は犬を怖がる。","exampleEn":"My little brother is afraid of dogs."},{"id":"gatai","kind":"pattern","tier":"morphological","labelJa":"～がたい","labelEn":"hard to do (literary)","jlpt":"N1","gloss":"literary masu-stem suffix expressing that an action is nearly impossible","exampleJa":"彼の話は信じがたい。","exampleEn":"His story is hard to believe."},{"id":"ge","kind":"pattern","tier":"morphological","labelJa":"～げ","labelEn":"the outward look of a feeling","jlpt":"N2","gloss":"suffix showing the outward look of an inner emotion or quality","exampleJa":"彼は寂しげな顔をしていた。","exampleEn":"He had a lonely-looking expression."},{"id":"go-kudasai","kind":"pattern","tier":"lexical","labelJa":"お／ご～ください","labelEn":"an honorific \\"please ...\\"","jlpt":"N3","gloss":"polite-honorific request formed with お/ご + verb stem or suru-noun + ください","exampleJa":"こちらの資料をご確認ください。","exampleEn":"Please check these materials."},{"id":"hajimeru","kind":"pattern","tier":"morphological","labelJa":"～始める","labelEn":"begin to do something","jlpt":"N3","gloss":"compound-verb aspect: the action begins (V-ます-stem + 始める)","exampleJa":"子供が泣き始めた。","exampleEn":"The child started crying."},{"id":"hanmen","kind":"pattern","tier":"lexical","labelJa":"～反面","labelEn":"while / on the other hand","jlpt":"N2","gloss":"contrasts two co-existing sides of the same thing: 'while / but on the other hand'","exampleJa":"便利な反面、危険もある。","exampleEn":"It's convenient, but on the other hand it's dangerous."},{"id":"hazu","kind":"pattern","tier":"lexical","labelJa":"～はずだ","labelEn":"should be / is supposed to (a confident expectation)","jlpt":"N3","gloss":"expresses a confident expectation based on reasoning: 'it should be that X' (affirmative はずだ; the negative はずがない is a separate entry)","exampleJa":"彼は来るはずだ。","exampleEn":"He should be coming."},{"id":"hazu-ga-nai","kind":"pattern","tier":"lexical","labelJa":"～はずがない","labelEn":"there's no way","jlpt":"N3","gloss":"expresses strong conviction that something is impossible","exampleJa":"彼が嘘をつくはずがない。","exampleEn":"There's no way he would lie."},{"id":"hodo","kind":"pattern","tier":"lexical","labelJa":"～ほど","labelEn":"extent, comparison, and \\"the more ... the more\\"","jlpt":"N3","gloss":"marks a degree of comparison or proportional change","exampleJa":"彼ほど親切な人はいない。","exampleEn":"There's no one as kind as him."},{"id":"ijou-wa","kind":"pattern","tier":"lexical","labelJa":"～以上（は）","labelEn":"now that / seeing that","jlpt":"N2","gloss":"given the established fact, an obligation or determination naturally follows","exampleJa":"学生である以上、勉強すべきだ。","exampleEn":"Now that you are a student, you ought to study."},{"id":"imperative","kind":"conjugation","tier":"morphological","labelJa":"命令形","labelEn":"direct command","jlpt":"N4","gloss":null,"exampleJa":"早く逃げろ！","exampleEn":"Run, quick!","category":"form"},{"id":"ippou-da","kind":"pattern","tier":"lexical","labelJa":"～一方だ","labelEn":"keeps changing in one direction","jlpt":"N2","gloss":"a situation continues to change in one direction only","exampleJa":"物価は上がる一方だ。","exampleEn":"Prices just keep going up."},{"id":"ippou-de","kind":"pattern","tier":"lexical","labelJa":"～一方で","labelEn":"while / on the other hand","jlpt":"N2","gloss":"contrasts two simultaneous aspects: 'while on the one hand X, on the other Y'","exampleJa":"給料は安い一方で楽だ。","exampleEn":"The pay is low, but on the other hand the work is easy."},{"id":"kagiri","kind":"pattern","tier":"lexical","labelJa":"～限り","labelEn":"as much as / to the limit","jlpt":"N2","gloss":"'as far/much as one can' (できる限り / 可能な限り) — to the utmost extent","exampleJa":"できる限り頑張る。","exampleEn":"I'll do my best, as much as I can."},{"id":"kakeru","kind":"pattern","tier":"morphological","labelJa":"～かける","labelEn":"halfway done, or on the verge of happening","jlpt":"N2","gloss":"the action started but is unfinished, or was on the verge of happening","exampleJa":"彼はおぼれて死にかけた。","exampleEn":"He nearly drowned."},{"id":"kamoshirenai","kind":"pattern","tier":"lexical","labelJa":"～かもしれない","labelEn":"might / maybe","jlpt":"N4","gloss":"expresses possibility or uncertainty about a statement","exampleJa":"明日雨が降るかもしれない。","exampleEn":"It might rain tomorrow."},{"id":"kanenai","kind":"pattern","tier":"morphological","labelJa":"～かねない","labelEn":"might do something, sth. might happen (undesirable)","jlpt":"N2","gloss":"warns that something undesirable could easily happen; the ない does NOT negate — the whole unit means 'might do'","exampleJa":"彼はそんなことを言いかねない。","exampleEn":"He might well say something like that."},{"id":"kaneru","kind":"pattern","tier":"morphological","labelJa":"～かねる","labelEn":"cannot do / find it hard to do (politely)","jlpt":"N2","gloss":"polite inability or reluctance to do something (often in formal refusals)","exampleJa":"その質問にはお答えしかねます。","exampleEn":"I am unable to answer that question."},{"id":"kano-youda","kind":"pattern","tier":"lexical","labelJa":"～かのよう","labelEn":"as if it were true (when it is not)","jlpt":"N2","gloss":"likens a situation to something that is not actually the case ('as if ...'); often with まるで","exampleJa":"彼は何も知らないかのように振る舞った。","exampleEn":"He behaved as if he knew nothing."},{"id":"kara-reason","kind":"pattern","tier":"morphological","labelJa":"～から","labelEn":"giving a reason (\\"because\\")","jlpt":"N5","gloss":"subjective reason/cause: 'because X' — the conjunctive (接続助詞) から after a predicate, not the case から ('from')","exampleJa":"忙しいから行けない。","exampleEn":"I can't go because I'm busy."},{"id":"kata-way","kind":"pattern","tier":"morphological","labelJa":"～方","labelEn":"how to do something, or the way it is done","jlpt":"N4","gloss":"turns a verb stem into 'the way of doing' it (読み方 how to read)","exampleJa":"この漢字の読み方を教えてください。","exampleEn":"Please tell me how to read this kanji."},{"id":"kawari-ni","kind":"pattern","tier":"lexical","labelJa":"～かわりに","labelEn":"instead of / in exchange for","jlpt":"N3","gloss":"'in place of / in exchange for' (V/N の代わりに)","exampleJa":"働く代わりにお金をもらう。","exampleEn":"I receive money in exchange for working."},{"id":"kedo","kind":"pattern","tier":"lexical","labelJa":"～けど","labelEn":"but / however","jlpt":"N5","gloss":"casual conjunction marking a contrast or qualification","exampleJa":"暑いけど、行く。","exampleEn":"It's hot, but I'll go."},{"id":"kirai-ga-aru","kind":"pattern","tier":"lexical","labelJa":"～きらいがある","labelEn":"has an (undesirable) tendency to","jlpt":"N1","gloss":"has an (undesirable) tendency or habit","exampleJa":"彼は物事を悲観的に考えるきらいがある。","exampleEn":"He has a tendency to think pessimistically."},{"id":"kiri","kind":"pattern","tier":"lexical","labelJa":"～たきり","labelEn":"ever since then, nothing has changed","jlpt":"N2","gloss":"after the action happened once, the situation has stayed that way","exampleJa":"彼女は出て行ったきり、戻らなかった。","exampleEn":"She left and never came back."},{"id":"kiru","kind":"pattern","tier":"morphological","labelJa":"～切る","labelEn":"do completely, to the very end","jlpt":"N2","gloss":"carry the action through to completion (使い切る); the potential negative 〜切れない means 'can't fully'","exampleJa":"ラーメンを最後まで食べきった。","exampleEn":"I finished the ramen down to the last bite."},{"id":"koro","kind":"pattern","tier":"lexical","labelJa":"～頃","labelEn":"around the time of / when","jlpt":"N4","gloss":"marks an approximate time or a period of life (子供の頃, 三時頃)","exampleJa":"子供の頃はよく川で泳いだ。","exampleEn":"When I was a child, I often swam in the river."},{"id":"koso","kind":"pattern","tier":"lexical","labelJa":"～こそ","labelEn":"precisely / exactly","jlpt":"N3","gloss":"singles the preceding word out emphatically as the very one","exampleJa":"今だからこそ、新しいことに挑戦するべきだ。","exampleEn":"Now is exactly the time to try something new."},{"id":"koto-ga-aru","kind":"pattern","tier":"lexical","labelJa":"～ことがある","labelEn":"past experience, or something that sometimes happens","jlpt":"N4","gloss":"expresses past experience (with た-form) or occasional occurrence (dictionary form)","exampleJa":"日本に行ったことがあります。","exampleEn":"I have been to Japan."},{"id":"koto-ga-dekiru","kind":"pattern","tier":"lexical","labelJa":"～ことができる","labelEn":"being able to do something","jlpt":"N5","gloss":"expresses ability or possibility with a dictionary-form verb","exampleJa":"日本語を話すことができます。","exampleEn":"I can speak Japanese."},{"id":"koto-ga-ooi","kind":"pattern","tier":"lexical","labelJa":"～ことが多い","labelEn":"often does / is often the case","jlpt":"N3","gloss":"states that the action happens in many cases / frequently","exampleJa":"週末は家で過ごすことが多い。","exampleEn":"I often spend weekends at home."},{"id":"koto-nashi-ni","kind":"pattern","tier":"lexical","labelJa":"～ことなしに","labelEn":"without ever doing","jlpt":"N1","gloss":"formal: the result is achieved without the first action happening","exampleJa":"犠牲にすることなしに、改革は進められない。","exampleEn":"The reform cannot proceed without making sacrifices."},{"id":"koto-ni-naru","kind":"pattern","tier":"lexical","labelJa":"～ことになる","labelEn":"it has been decided that","jlpt":"N4","gloss":"indicates a decision or outcome reached by circumstance rather than the speaker","exampleJa":"来月転勤することになりました。","exampleEn":"It has been decided that I will be transferred next month."},{"id":"koto-ni-suru","kind":"pattern","tier":"lexical","labelJa":"～ことにする","labelEn":"deciding to do something","jlpt":"N3","gloss":"expresses a decision the speaker makes (contrast ことになる, which is a decision arrived at externally)","exampleJa":"毎朝走ることにする。","exampleEn":"I've decided to run every morning."},{"id":"ku-naru","kind":"pattern","tier":"morphological","labelJa":"～くなる","labelEn":"becoming a different state","jlpt":"N5","gloss":"marks change of state with i-adjectives via the ku-form plus naru","exampleJa":"最近、寒くなってきた。","exampleEn":"It's been getting cold lately."},{"id":"kurai","kind":"pattern","tier":"morphological","labelJa":"～くらい","labelEn":"about this much, to this extent","jlpt":"N4","gloss":"indicates an approximate amount or the extent to which something holds","exampleJa":"泣きたいくらい嬉しかった。","exampleEn":"I was so happy I could have cried."},{"id":"kuse-ni","kind":"pattern","tier":"lexical","labelJa":"～くせに","labelEn":"\\"even though\\" with a tone of criticism","jlpt":"N3","gloss":"concessive 'even though', carrying criticism or reproach toward the subject","exampleJa":"知っているくせに教えない。","exampleEn":"He won't tell me, even though he knows."},{"id":"mae-ni","kind":"pattern","tier":"lexical","labelJa":"～前に","labelEn":"\\"before\\" doing something","jlpt":"N3","gloss":"temporal 前に: 'before' (V-る前に / N の前に) or 'ago' (三年前に); distinct from the bare noun 前 'in front of'","exampleJa":"寝る前に歯を磨く。","exampleEn":"I brush my teeth before going to bed."},{"id":"mama","kind":"pattern","tier":"lexical","labelJa":"～まま","labelEn":"leaving a state as it is","jlpt":"N4","gloss":"indicates that a state remains unchanged while another action occurs","exampleJa":"靴を履いたまま入らないで。","exampleEn":"Don't come in with your shoes on."},{"id":"maru-de","kind":"pattern","tier":"lexical","labelJa":"まるで","labelEn":"just like / as if","jlpt":"N3","gloss":"adverb that sets up and intensifies a simile resolved by ようだ/みたい","exampleJa":"彼女の笑顔はまるで夢のようだ。","exampleEn":"Her smile is just like a dream."},{"id":"me","kind":"pattern","tier":"morphological","labelJa":"～め","labelEn":"on the somewhat X side","jlpt":"N3","gloss":"attaches to adjective stems to mean slightly or rather toward that quality","exampleJa":"ご飯は少なめにしてください。","exampleEn":"Please make the rice portion on the small side."},{"id":"mitai","kind":"pattern","tier":"lexical","labelJa":"～みたい","labelEn":"like / seems like","jlpt":"N3","gloss":"colloquial comparison or conjecture marker, similar to ようだ","exampleJa":"まるで夢みたいだ。","exampleEn":"It's just like a dream."},{"id":"mono-da","kind":"pattern","tier":"lexical","labelJa":"～ものだ","labelEn":"how things were, are, or should be","jlpt":"N3","gloss":"states a general truth, nostalgic recollection, or social expectation (昔はよく…したものだ)","exampleJa":"子供の頃はよく泳いだものだ。","exampleEn":"I used to swim a lot as a child."},{"id":"monono","kind":"pattern","tier":"lexical","labelJa":"～ものの","labelEn":"although / but (the expected result did not follow)","jlpt":"N2","gloss":"concedes the first clause is true while the expected result does not follow","exampleJa":"約束したものの、行きたくない。","exampleEn":"Although I promised, I don't want to go."},{"id":"na-adverbial","kind":"conjugation","tier":"morphological","labelJa":"な-Adj+に","labelEn":"na-adjective adverbial","jlpt":"N5","gloss":null,"exampleJa":"図書館では静かに話してください。","exampleEn":"Please speak quietly in the library.","category":"form"},{"id":"nagara","kind":"pattern","tier":"lexical","labelJa":"～ながら","labelEn":"doing two things at once","jlpt":"N4","gloss":"indicates two simultaneous actions or a concessive contrast","exampleJa":"音楽を聞きながら勉強する。","exampleEn":"I study while listening to music."},{"id":"nagara-mo","kind":"pattern","tier":"lexical","labelJa":"～ながらも","labelEn":"even though / while being","jlpt":"N2","gloss":"concessive: despite the state in the first clause, the second holds","exampleJa":"彼は若いながらも、経験が豊富だ。","exampleEn":"Even though he is young, he has plenty of experience."},{"id":"nagara-ni","kind":"pattern","tier":"lexical","labelJa":"～ながらに","labelEn":"in a state of, while remaining as is","jlpt":"N1","gloss":"fixed expressions of state: 涙ながらに in tears, 生まれながらに by birth","exampleJa":"祖母は涙ながらに語った。","exampleEn":"My grandmother spoke in tears."},{"id":"nai-plain","kind":"pattern","tier":"morphological","labelJa":"～ない","labelEn":"the plain way to say \\"not\\"","jlpt":"N5","gloss":"plain negative auxiliary attaching to verbs to form the basic negative","exampleJa":"今日は何も食べない。","exampleEn":"I'm not eating anything today."},{"id":"naide","kind":"pattern","tier":"morphological","labelJa":"～ないで","labelEn":"without doing","jlpt":"N4","gloss":"does the second action without doing the first","exampleJa":"朝ご飯を食べないで学校に行った。","exampleEn":"I went to school without eating breakfast."},{"id":"naide-kudasai","kind":"pattern","tier":"lexical","labelJa":"～ないでください","labelEn":"please don't","jlpt":"N5","gloss":"polite negative request","exampleJa":"ここで写真を撮らないでください。","exampleEn":"Please don't take photos here."},{"id":"nante","kind":"pattern","tier":"lexical","labelJa":"～なんて","labelEn":"such a thing as ...","jlpt":"N3","gloss":"expresses surprise, dismissal, or quoted reference","exampleJa":"勉強なんてしたくない。","exampleEn":"I don't want to do something like studying."},{"id":"nara","kind":"pattern","tier":"lexical","labelJa":"～なら","labelEn":"\\"if that's the case\\" conditional","jlpt":"N3","gloss":"supposition / topic-conditional: 'if it's the case that' or 'as for' (often picking up the listener's topic)","exampleJa":"日本へ行くなら京都がおすすめだ。","exampleEn":"If you're going to Japan, I recommend Kyoto."},{"id":"nari","kind":"pattern","tier":"lexical","labelJa":"～なり","labelEn":"as soon as","jlpt":"N1","gloss":"immediately upon the first action, the (often unexpected) second follows","exampleJa":"電話が鳴るなり、彼女は部屋を出て行った。","exampleEn":"The moment the phone rang, she left the room."},{"id":"negative","kind":"conjugation","tier":"morphological","labelJa":"～ない","labelEn":"negative","jlpt":"N5","gloss":null,"exampleJa":"肉を食べない。","exampleEn":"I don't eat meat.","category":"tense-polite"},{"id":"negative-command","kind":"conjugation","tier":"morphological","labelJa":"～な","labelEn":"don't (prohibitive)","jlpt":"N4","gloss":null,"exampleJa":"ここで遊ぶな。","exampleEn":"Don't play here.","category":"form"},{"id":"ni-atatte","kind":"pattern","tier":"lexical","labelJa":"～にあたって","labelEn":"on the occasion of, at the juncture of","jlpt":"N2","gloss":"formal: at the (important) juncture of starting or doing something","exampleJa":"新製品の発売にあたって、記者会見を開いた。","exampleEn":"On the occasion of the product launch, a press conference was held."},{"id":"ni-chigainai","kind":"pattern","tier":"lexical","labelJa":"～に違いない","labelEn":"it must be / there's no doubt","jlpt":"N3","gloss":"expresses strong certainty based on evidence or inference","exampleJa":"彼は犯人に違いない。","exampleEn":"He must be the culprit."},{"id":"ni-kagirazu","kind":"pattern","tier":"lexical","labelJa":"～に限らず","labelEn":"not limited to / not just","jlpt":"N2","gloss":"'not just X (but more widely)' — extends beyond the stated case","exampleJa":"週末に限らず混んでいる。","exampleEn":"It's crowded, and not just on weekends."},{"id":"ni-kanshite","kind":"pattern","tier":"lexical","labelJa":"～に関して","labelEn":"regarding (formal)","jlpt":"N2","gloss":"indicates the topic of discussion in a more formal register than について","exampleJa":"この事件に関して質問があります。","exampleEn":"I have a question regarding this incident."},{"id":"ni-kimatte-iru","kind":"pattern","tier":"lexical","labelJa":"～に決まっている","labelEn":"it's definitely so","jlpt":"N3","gloss":"expresses the speaker's strong conviction or certainty","exampleJa":"うそに決まっている。","exampleEn":"It's definitely a lie."},{"id":"ni-kuwaete","kind":"pattern","tier":"lexical","labelJa":"～に加えて","labelEn":"in addition to","jlpt":"N2","gloss":"'in addition to / on top of' — adds a further item or factor","exampleJa":"雨に加えて風も強い。","exampleEn":"In addition to the rain, the wind is strong."},{"id":"ni-mo-kakawarazu","kind":"pattern","tier":"lexical","labelJa":"～にもかかわらず","labelEn":"in spite of / despite","jlpt":"N2","gloss":"expresses an outcome contrary to what is expected from the preceding fact","exampleJa":"雨にもかかわらず試合は続いた。","exampleEn":"Despite the rain, the match continued."},{"id":"ni-motozuite","kind":"pattern","tier":"lexical","labelJa":"～に基づいて","labelEn":"based on","jlpt":"N2","gloss":"indicates the basis or foundation for an action or judgment","exampleJa":"事実に基づいて判断する。","exampleEn":"Judge based on the facts."},{"id":"ni-naru","kind":"pattern","tier":"morphological","labelJa":"～になる","labelEn":"to become","jlpt":"N5","gloss":"change of state into the preceding noun or na-adjective","exampleJa":"兄は医者になった。","exampleEn":"My brother became a doctor."},{"id":"ni-oite","kind":"pattern","tier":"lexical","labelJa":"～において","labelEn":"in / at (formal)","jlpt":"N3","gloss":"formal marker of place, time, or situation: 'in / at / on the occasion of'","exampleJa":"会議において発表する。","exampleEn":"I will present at the meeting."},{"id":"ni-shitemo","kind":"pattern","tier":"lexical","labelJa":"～にしても","labelEn":"even if, even granting that","jlpt":"N2","gloss":"concessive 'even if / even granting that'; also 'whether ... or'","exampleJa":"どんなに高いにしても買う。","exampleEn":"I'll buy it even if it's expensive."},{"id":"ni-shitewa","kind":"pattern","tier":"lexical","labelJa":"～にしては","labelEn":"surprisingly good (or bad) for ...","jlpt":"N2","gloss":"'for / considering (that it's X)', noting a result that doesn't match the expectation set by X","exampleJa":"初めてにしては上手だ。","exampleEn":"You're good, for a first-timer."},{"id":"ni-suginai","kind":"pattern","tier":"lexical","labelJa":"～に過ぎない","labelEn":"nothing more than","jlpt":"N3","gloss":"'is no more than / merely' — downplays X as insignificant","exampleJa":"それは噂に過ぎない。","exampleEn":"That's nothing more than a rumor."},{"id":"ni-taishite","kind":"pattern","tier":"lexical","labelJa":"～に対して","labelEn":"toward a target, or in contrast","jlpt":"N3","gloss":"marks the target of an action or attitude, or sets up a contrast","exampleJa":"学生に対して優しい先生です。","exampleEn":"He is a teacher who is kind toward students."},{"id":"ni-totte","kind":"pattern","tier":"lexical","labelJa":"～にとって","labelEn":"from someone's standpoint","jlpt":"N3","gloss":"expresses a viewpoint or standpoint from which something is evaluated","exampleJa":"私にとって家族は大切です。","exampleEn":"For me, family is important."},{"id":"ni-tsuite","kind":"pattern","tier":"lexical","labelJa":"～について","labelEn":"talking about a topic","jlpt":"N3","gloss":"indicates the topic or subject being discussed","exampleJa":"日本の歴史について話します。","exampleEn":"I will talk about Japanese history."},{"id":"ni-tsurete","kind":"pattern","tier":"lexical","labelJa":"～につれて","labelEn":"as one thing changes, so does another","jlpt":"N3","gloss":"expresses a proportional change: 'as X (progresses), Y (changes too)'","exampleJa":"年を取るにつれて体が弱くなる。","exampleEn":"As you age, your body grows weaker."},{"id":"ni-yoru-to","kind":"pattern","tier":"lexical","labelJa":"～によると","labelEn":"according to (a source)","jlpt":"N4","gloss":"cites the source of reported information, usually paired with a clause-final そうだ / らしい","exampleJa":"天気予報によると明日は雨だ。","exampleEn":"According to the forecast, it will rain tomorrow."},{"id":"ni-yotte","kind":"pattern","tier":"lexical","labelJa":"～によって","labelEn":"depending on / by means of / by","jlpt":"N3","gloss":"'depending on', 'by means of', or the passive agent 'by'; varies with the situation","exampleJa":"時代によって考え方が違う。","exampleEn":"Ways of thinking differ depending on the era."},{"id":"nikui","kind":"pattern","tier":"morphological","labelJa":"～にくい","labelEn":"difficult to do","jlpt":"N3","gloss":"attaches to masu-stem to mark that an action is hard to perform","exampleJa":"この字は読みにくいです。","exampleEn":"This handwriting is hard to read."},{"id":"no-nominalizer","kind":"pattern","tier":"lexical","labelJa":"の（名詞化）","labelEn":"turning an action into a noun","jlpt":"N4","gloss":"の turns a verb/adjective clause into a noun phrase (the act/fact of doing), as opposed to the genitive の (possession)","exampleJa":"日本語を話すのが好きだ。","exampleEn":"I like speaking Japanese."},{"id":"no-youda","kind":"pattern","tier":"lexical","labelJa":"～のようだ","labelEn":"like / as if (comparing to a noun)","jlpt":"N4","gloss":"likens the subject to the preceding noun (のように / のような before words)","exampleJa":"彼女の笑顔はまるで夢のようだ。","exampleEn":"Her smile is just like a dream."},{"id":"noda","kind":"pattern","tier":"lexical","labelJa":"～のだ","labelEn":"giving an explanation","jlpt":"N4","gloss":"provides an explanation, reason, or emphasizes a fact","exampleJa":"頭が痛いんです。","exampleEn":"It's that I have a headache."},{"id":"node","kind":"pattern","tier":"lexical","labelJa":"～ので","labelEn":"because / since","jlpt":"N5","gloss":"states a reason; softer and more objective than から. After nouns/na-adjectives it appears as なので","exampleJa":"忙しいので、行けません。","exampleEn":"I can't go because I'm busy."},{"id":"noni","kind":"pattern","tier":"lexical","labelJa":"～のに","labelEn":"although / despite","jlpt":"N4","gloss":"expresses surprise or dissatisfaction that the result contradicts expectation","exampleJa":"勉強したのに、テストに落ちた。","exampleEn":"Even though I studied, I failed the test."},{"id":"noni-purpose","kind":"pattern","tier":"lexical","labelJa":"～のに（使う・必要だ）","labelEn":"for the purpose of","jlpt":"N3","gloss":"nominalised purpose: the clause states what something is used for or needed for","exampleJa":"この本を読むのに辞書を使う。","exampleEn":"I use a dictionary to read this book."},{"id":"obligation-nakereba","kind":"pattern","tier":"lexical","labelJa":"～なければならない","labelEn":"must, have to","jlpt":"N4","gloss":"expresses obligation, literally 'if you don't X it won't do'; casual contractions なきゃ / なくちゃ","exampleJa":"毎日勉強しなければならない。","exampleEn":"I have to study every day."},{"id":"okage-de","kind":"pattern","tier":"lexical","labelJa":"～おかげで","labelEn":"thanks to","jlpt":"N3","gloss":"attributes a (usually positive) result to a cause; the grateful counterpart of ～せいで","exampleJa":"先生のおかげで合格できました。","exampleEn":"Thanks to my teacher, I was able to pass."},{"id":"passive","kind":"conjugation","tier":"morphological","labelJa":"～（ら）れる","labelEn":"passive, is done / gets done","jlpt":"N4","gloss":null,"exampleJa":"私は先生に褒められた。","exampleEn":"I was praised by the teacher.","category":"voice"},{"id":"past","kind":"conjugation","tier":"morphological","labelJa":"～た","labelEn":"plain past tense","jlpt":"N5","gloss":null,"exampleJa":"昨日、映画を見た。","exampleEn":"I watched a movie yesterday.","category":"tense-polite"},{"id":"polite","kind":"conjugation","tier":"morphological","labelJa":"～ます／です","labelEn":"polite style","jlpt":"N5","gloss":null,"exampleJa":"毎朝、コーヒーを飲みます。","exampleEn":"I drink coffee every morning.","category":"tense-polite"},{"id":"potential","kind":"conjugation","tier":"morphological","labelJa":"～（ら）れる／～える","labelEn":"can, be able to","jlpt":"N4","gloss":null,"exampleJa":"私は日本語が話せます。","exampleEn":"I can speak Japanese.","category":"voice"},{"id":"ppanashi","kind":"pattern","tier":"morphological","labelJa":"～っぱなし","labelEn":"leaving something on, open, or running","jlpt":"N2","gloss":"'leave (something) in a state' — left on, open, or running (つけっぱなし, 出しっぱなし)","exampleJa":"電気をつけっぱなしにする。","exampleEn":"I leave the light on."},{"id":"ppoi","kind":"pattern","tier":"morphological","labelJa":"～っぽい","labelEn":"-ish / -like / tends to","jlpt":"N3","gloss":"derives an i-adjective meaning 'has the qualities of / tends to' (子供っぽい, 忘れっぽい)","exampleJa":"彼は子供っぽい。","exampleEn":"He's childish."},{"id":"presumptive","kind":"conjugation","tier":"morphological","labelJa":"～だろう／でしょう","labelEn":"probably (presumptive)","jlpt":"N5","gloss":null,"exampleJa":"明日はたぶん晴れるだろう。","exampleEn":"It will probably be sunny tomorrow.","category":"form"},{"id":"provisional-ba","kind":"conjugation","tier":"morphological","labelJa":"～ば","labelEn":"provisional conditional \\"if\\"","jlpt":"N4","gloss":null,"exampleJa":"ボタンを押せば、ドアが開きます。","exampleEn":"If you press the button, the door opens.","category":"form"},{"id":"ra-plural","kind":"conjugation","tier":"morphological","labelJa":"～たち／～ら","labelEn":"plural suffix for people","jlpt":"N3","gloss":null,"exampleJa":"子供たちは公園で遊んでいる。","exampleEn":"The children are playing in the park.","category":"form"},{"id":"rashii","kind":"pattern","tier":"morphological","labelJa":"～らしい","labelEn":"seems or apparently","jlpt":"N4","gloss":"marks an inference based on reliable external information or hearsay","exampleJa":"彼は来ないらしい。","exampleEn":"Apparently he isn't coming."},{"id":"rou","kind":"pattern","tier":"morphological","labelJa":"～だろう","labelEn":"probably or surely","jlpt":"N4","gloss":"plain conjectural auxiliary expressing the speaker's guess or supposition","exampleJa":"明日は晴れるだろう。","exampleEn":"It will probably be sunny tomorrow."},{"id":"sa-noun","kind":"pattern","tier":"morphological","labelJa":"～さ","labelEn":"turning an adjective into a noun of degree","jlpt":"N4","gloss":"turns an i- or na-adjective into a noun expressing its degree or extent","exampleJa":"この山の高さは三千メートルです。","exampleEn":"This mountain's height is three thousand meters."},{"id":"sae","kind":"pattern","tier":"lexical","labelJa":"～さえ","labelEn":"even","jlpt":"N3","gloss":"emphasises an extreme example ('even X'); さえ～ば marks the sole condition","exampleJa":"あの子は自分の名前さえ書けない。","exampleEn":"That child can't even write his own name."},{"id":"sai","kind":"pattern","tier":"lexical","labelJa":"～際に","labelEn":"formal \\"when\\" / \\"on the occasion of\\"","jlpt":"N2","gloss":"formal 'at the time of / when' (V-る/た際に, N の際に)","exampleJa":"帰国の際にお土産を買った。","exampleEn":"I bought souvenirs when I returned home."},{"id":"saichuu","kind":"pattern","tier":"lexical","labelJa":"～最中","labelEn":"right in the middle of doing something","jlpt":"N2","gloss":"'right in the middle of (doing)' — an action interrupted partway (さいちゅう, not the もなか sweet)","exampleJa":"食事の最中に電話が鳴った。","exampleEn":"The phone rang right in the middle of dinner."},{"id":"sei-de","kind":"pattern","tier":"lexical","labelJa":"～せいで","labelEn":"because of / due to (blame)","jlpt":"N3","gloss":"attributes a negative result to a cause; the blaming counterpart of ～おかげで","exampleJa":"雨のせいで試合が中止になった。","exampleEn":"Because of the rain, the match was cancelled."},{"id":"shi","kind":"pattern","tier":"morphological","labelJa":"～し","labelEn":"listing reasons","jlpt":"N4","gloss":"lists co-ordinate reasons or qualities: 'X, and (what's more) Y ...'","exampleJa":"安いし、便利だ。","exampleEn":"It's cheap, and (besides) convenient."},{"id":"shidai","kind":"pattern","tier":"lexical","labelJa":"～次第","labelEn":"as soon as (formal)","jlpt":"N2","gloss":"the next action happens immediately once the first is complete (formal register)","exampleJa":"準備ができ次第、出発します。","exampleEn":"We will depart as soon as preparations are complete."},{"id":"shika-nai","kind":"pattern","tier":"lexical","labelJa":"～しかない","labelEn":"only / no choice but to","jlpt":"N4","gloss":"expresses 'nothing but' or the sole remaining option, always with negative verb","exampleJa":"やるしかない。","exampleEn":"There's no choice but to do it."},{"id":"sorede","kind":"pattern","tier":"lexical","labelJa":"それで","labelEn":"and then / so","jlpt":"N4","gloss":"connects cause and resulting event in narrative","exampleJa":"それで、どうしたの？","exampleEn":"And then what happened?"},{"id":"sou-appearance","kind":"pattern","tier":"morphological","labelJa":"～そう","labelEn":"looks like or appears","jlpt":"N4","gloss":"conjectural そう based on visual impression; attaches to verb stem or i-adjective stem","exampleJa":"このケーキは美味しそう。","exampleEn":"This cake looks delicious."},{"id":"sou-hearsay","kind":"pattern","tier":"lexical","labelJa":"～そうだ","labelEn":"I hear that / reportedly","jlpt":"N4","gloss":"reports information heard from another source; attaches to plain form","exampleJa":"彼は来るそうだ。","exampleEn":"I hear he's coming."},{"id":"sou-negative","kind":"pattern","tier":"morphological","labelJa":"～そうにない","labelEn":"doesn't look like it will","jlpt":"N3","gloss":"negative of appearance そう; situation appears unlikely to occur","exampleJa":"雨は降りそうにない。","exampleEn":"It doesn't look like it will rain."},{"id":"sue-ni","kind":"pattern","tier":"lexical","labelJa":"～た末（に）","labelEn":"after a long process, finally","jlpt":"N2","gloss":"a result reached after a long process of doing the first action","exampleJa":"考えた末に、留学を決めた。","exampleEn":"After much thought, I decided to study abroad."},{"id":"sugiru","kind":"pattern","tier":"morphological","labelJa":"～すぎる","labelEn":"too much, overly","jlpt":"N4","gloss":"attaches to masu-stem or adjective stem to mean too much or overly so","exampleJa":"昨日は食べすぎてしまった。","exampleEn":"I ended up eating too much yesterday."},{"id":"suru","kind":"pattern","tier":"morphological","labelJa":"～する","labelEn":"turning an action noun into a verb","jlpt":"N5","gloss":"turns a verbal noun (sahen noun) into a verb","exampleJa":"毎日勉強する。","exampleEn":"I study every day."},{"id":"suru-itasu","kind":"pattern","tier":"morphological","labelJa":"～いたす","labelEn":"humble \\"do\\" for your own actions","jlpt":"N3","gloss":"humble (kenjougo) replacement for する, lowering the speaker's action","exampleJa":"失礼いたします。","exampleEn":"Excuse me (humble)."},{"id":"suru-sareru","kind":"pattern","tier":"morphological","labelJa":"～される","labelEn":"passive or respectful する","jlpt":"N3","gloss":"passive or respectful (sonkeigo) form of する attached to verbal nouns","exampleJa":"先生が研究される。","exampleEn":"The teacher does research (respectful)."},{"id":"suru-saseru","kind":"pattern","tier":"morphological","labelJa":"～させる","labelEn":"making or letting someone do something","jlpt":"N4","gloss":"causative form of する; makes or lets someone perform the vs-noun action","exampleJa":"子供に勉強させる。","exampleEn":"I make my child study."},{"id":"ta-bakari","kind":"pattern","tier":"lexical","labelJa":"～たばかり","labelEn":"it just happened","jlpt":"N4","gloss":"the action happened only a moment / short time ago","exampleJa":"日本に着いたばかりです。","exampleEn":"I have just arrived in Japan."},{"id":"tabini","kind":"pattern","tier":"lexical","labelJa":"～たびに","labelEn":"every time / each time","jlpt":"N3","gloss":"indicates that something happens whenever the preceding event occurs","exampleJa":"会うたびに笑顔になる。","exampleEn":"Every time we meet, I smile."},{"id":"tai","kind":"pattern","tier":"morphological","labelJa":"～たい","labelEn":"want to do something","jlpt":"N5","gloss":"expresses the speaker's desire to perform an action; attaches to verb masu-stem","exampleJa":"水が飲みたい。","exampleEn":"I want to drink water."},{"id":"tame-ni","kind":"pattern","tier":"lexical","labelJa":"～ために","labelEn":"in order to / because of","jlpt":"N4","gloss":"marks a purpose (with a verb or volitional) or a cause (with a noun or past clause)","exampleJa":"健康のために毎日運動します。","exampleEn":"I exercise every day for my health."},{"id":"tara-conditional","kind":"conjugation","tier":"morphological","labelJa":"～たら","labelEn":"if / when","jlpt":"N4","gloss":null,"exampleJa":"雨が降ったら、行きません。","exampleEn":"If it rains, I won't go.","category":"form"},{"id":"tari-form","kind":"conjugation","tier":"morphological","labelJa":"～たり","labelEn":"doing things like A and B","jlpt":"N5","gloss":null,"exampleJa":"昨日のパーティーでは、食べたり飲んだりしました。","exampleEn":"At yesterday's party we did things like eat and drink.","category":"form"},{"id":"te-aru","kind":"pattern","tier":"morphological","labelJa":"～てある","labelEn":"a state someone left on purpose","jlpt":"N4","gloss":"indicates a state remaining from a deliberate prior action, usually with transitive verbs","exampleJa":"ドアに鍵がかけてある。","exampleEn":"The door is locked (someone locked it)."},{"id":"te-bakari","kind":"pattern","tier":"morphological","labelJa":"～てばかり","labelEn":"doing nothing but","jlpt":"N2","gloss":"'do nothing but V' — repeated/excessive action (遊んでばかりいる)","exampleJa":"遊んでばかりいる。","exampleEn":"He does nothing but play."},{"id":"te-form","kind":"conjugation","tier":"morphological","labelJa":"～て／で","labelEn":"the connective te-form","jlpt":"N5","gloss":null,"exampleJa":"朝ご飯を食べて、学校に行った。","exampleEn":"I ate breakfast and went to school.","category":"form"},{"id":"te-hoshii","kind":"pattern","tier":"morphological","labelJa":"～てほしい","labelEn":"I want you (or someone) to do it","jlpt":"N4","gloss":"the speaker wants someone else to perform the action","exampleJa":"ちょっと手伝ってほしい。","exampleEn":"I want you to help me a little."},{"id":"te-ii","kind":"pattern","tier":"morphological","labelJa":"～てもいい","labelEn":"it is okay to do something","jlpt":"N5","gloss":"expresses permission, meaning it is acceptable to do something","exampleJa":"ここに座ってもいいですか。","exampleEn":"May I sit here?"},{"id":"te-iku","kind":"pattern","tier":"morphological","labelJa":"～ていく","labelEn":"an action or change moving away from the speaker","jlpt":"N4","gloss":"expresses motion away from the speaker or gradual change continuing into the future","exampleJa":"これから寒くなっていく。","exampleEn":"It will gradually get colder from now on."},{"id":"te-iru","kind":"pattern","tier":"morphological","labelJa":"～ている","labelEn":"ongoing action or resulting state","jlpt":"N5","gloss":"indicates an ongoing action or a state resulting from a past action","exampleJa":"今、本を読んでいます。","exampleEn":"I'm reading a book right now."},{"id":"te-itadaku","kind":"pattern","tier":"morphological","labelJa":"～ていただく","labelEn":"humbly receiving the favor of an action","jlpt":"N4","gloss":"humble equivalent of てもらう, marking received favor with deference","exampleJa":"先生に書いていただきました。","exampleEn":"I had the teacher write it (humbly)."},{"id":"te-kara","kind":"pattern","tier":"morphological","labelJa":"～てから","labelEn":"after doing one thing, do another","jlpt":"N5","gloss":"the second action happens after the first is done","exampleJa":"家に帰ってから宿題をする。","exampleEn":"I do my homework after coming home."},{"id":"te-kudasai","kind":"pattern","tier":"morphological","labelJa":"～てください","labelEn":"please do something","jlpt":"N5","gloss":"makes a polite request or gives a soft instruction","exampleJa":"ちょっと待ってください。","exampleEn":"Please wait a moment."},{"id":"te-kureru","kind":"pattern","tier":"morphological","labelJa":"～てくれる","labelEn":"someone does something for me","jlpt":"N4","gloss":"indicates someone does something as a favor for the speaker or in-group","exampleJa":"友達が手伝ってくれた。","exampleEn":"My friend helped me out."},{"id":"te-kuru","kind":"pattern","tier":"morphological","labelJa":"～てくる","labelEn":"an action or change coming toward the speaker","jlpt":"N4","gloss":"expresses motion toward the speaker, return, or gradual change emerging up to now","exampleJa":"雨が降ってきた。","exampleEn":"It started to rain."},{"id":"te-miru","kind":"pattern","tier":"morphological","labelJa":"～てみる","labelEn":"try doing something and see how it goes","jlpt":"N3","gloss":"do something to see how it goes — 'try V-ing' (て-form + みる)","exampleJa":"この服を着てみる。","exampleEn":"I'll try the clothes on."},{"id":"te-morau","kind":"pattern","tier":"morphological","labelJa":"～てもらう","labelEn":"have someone do something for you","jlpt":"N4","gloss":"indicates the speaker receives the favor of someone performing an action","exampleJa":"先生に教えてもらった。","exampleEn":"I had the teacher teach me."},{"id":"te-oku","kind":"pattern","tier":"morphological","labelJa":"～ておく","labelEn":"do something now, ready for later","jlpt":"N4","gloss":"indicates doing something in advance or leaving a state in place for later","exampleJa":"ビールを冷やしておく。","exampleEn":"I'll chill the beer in advance."},{"id":"te-oru","kind":"pattern","tier":"morphological","labelJa":"～ておる","labelEn":"humble or old-fashioned ている","jlpt":"N3","gloss":"humble or literary equivalent of ている, common in keigo and Kansai speech","exampleJa":"お待ちしております。","exampleEn":"I am waiting (humbly)."},{"id":"te-shimau","kind":"pattern","tier":"morphological","labelJa":"～てしまう","labelEn":"regret or complete finish","jlpt":"N4","gloss":"indicates accidental, regrettable, or fully completed action","exampleJa":"宿題を忘れてしまった。","exampleEn":"I went and forgot my homework."},{"id":"te-wa-ikenai","kind":"pattern","tier":"lexical","labelJa":"～てはいけない","labelEn":"you must not do it","jlpt":"N4","gloss":"expresses prohibition — 'you must not do X'; casual contractions ～ちゃだめ / ～ちゃいけない","exampleJa":"ここに入ってはいけない。","exampleEn":"You must not enter here."},{"id":"te-yagaru","kind":"pattern","tier":"morphological","labelJa":"～てやがる","labelEn":"contempt for what someone is doing","jlpt":"N1","gloss":"expresses anger or contempt toward another's action, very rough register","exampleJa":"何を言ってやがる。","exampleEn":"What the hell are you saying?"},{"id":"temo","kind":"pattern","tier":"morphological","labelJa":"～ても／でも","labelEn":"even if / even though","jlpt":"N4","gloss":"concessive: 'even if X (then still) ...' — the て/で-form plus も grants the condition no effect","exampleJa":"食べても太らない。","exampleEn":"Even if I eat, I won't gain weight."},{"id":"tewa","kind":"pattern","tier":"morphological","labelJa":"～ては／では","labelEn":"if / when (and so)","jlpt":"N4","gloss":"the て/で-form plus は: marks a (typically undesirable) recurring condition, the base of てはいけない","exampleJa":"ここでタバコを吸ってはいけない。","exampleEn":"You must not smoke here."},{"id":"to-atte","kind":"pattern","tier":"lexical","labelJa":"～とあって","labelEn":"given that / since (special occasion)","jlpt":"N1","gloss":"because of the special circumstance, the (expected) consequence follows","exampleJa":"人気俳優が出演するとあって、前売り券は売り切れた。","exampleEn":"Since a popular actor was appearing, advance tickets sold out."},{"id":"to-conditional","kind":"pattern","tier":"morphological","labelJa":"～と","labelEn":"when one thing happens, another naturally follows","jlpt":"N4","gloss":"whenever the first clause holds, the second follows naturally or habitually","exampleJa":"春になると桜が咲く。","exampleEn":"When spring comes, the cherry trees bloom."},{"id":"to-itte-mo","kind":"pattern","tier":"lexical","labelJa":"～といっても","labelEn":"although I say so, it's less than you think","jlpt":"N2","gloss":"concedes a statement while qualifying it with a contrasting reality","exampleJa":"料理ができるといっても卵焼きだけです。","exampleEn":"Although I say I can cook, it's only fried eggs."},{"id":"to-iu","kind":"pattern","tier":"lexical","labelJa":"～という","labelEn":"a person called X, a thing called X","jlpt":"N4","gloss":"names or identifies the following noun (a person called X, the fact that X)","exampleJa":"田中さんという人を知っていますか。","exampleEn":"Do you know a person called Tanaka?"},{"id":"to-wa","kind":"pattern","tier":"lexical","labelJa":"～とは","labelEn":"defining or asking what something really is","jlpt":"N3","gloss":"marks a topic being defined or quoted for emphasis","exampleJa":"自由とは何か。","exampleEn":"What is freedom?"},{"id":"toki","kind":"pattern","tier":"lexical","labelJa":"～とき","labelEn":"when / at the time of","jlpt":"N5","gloss":"marks the time at which an action or state occurs","exampleJa":"子供のとき、よく泳ぎました。","exampleEn":"When I was a child, I often swam."},{"id":"tokoro-aspect","kind":"pattern","tier":"lexical","labelJa":"～ところ","labelEn":"just did / in the middle of / just about to","jlpt":"N4","gloss":"marks an aspectual stage: just finished (～たところ), in the middle of (～ているところ) or just about to (～るところ)","exampleJa":"今食べたところだ。","exampleEn":"I just finished eating."},{"id":"tokoro-wo","kind":"pattern","tier":"lexical","labelJa":"～ところを","labelEn":"in the act of / scene of","jlpt":"N2","gloss":"someone is observed or caught right at the moment of doing the action","exampleJa":"子供たちがサッカーをするところを見た。","exampleEn":"I saw the children playing soccer."},{"id":"tokorode","kind":"pattern","tier":"lexical","labelJa":"ところで","labelEn":"by the way / incidentally","jlpt":"N3","gloss":"changes the topic in conversation","exampleJa":"ところで、明日は何する？","exampleEn":"By the way, what are you doing tomorrow?"},{"id":"tokoroga","kind":"pattern","tier":"lexical","labelJa":"ところが","labelEn":"however / unexpectedly","jlpt":"N3","gloss":"introduces an unexpected or contrary outcome","exampleJa":"ところが、雨が降り出した。","exampleEn":"However, it started raining."},{"id":"tomonaru-to","kind":"pattern","tier":"lexical","labelJa":"～ともなると","labelEn":"when it comes to being (that level)","jlpt":"N1","gloss":"once the status reaches that (high) level, things are naturally different","exampleJa":"大企業の社長ともなると、スケジュールは分単位だ。","exampleEn":"When you're the president of a big company, your schedule runs by the minute."},{"id":"toshite","kind":"pattern","tier":"lexical","labelJa":"～として","labelEn":"as / in the capacity of","jlpt":"N3","gloss":"marks the role, status, or capacity in which someone or something acts","exampleJa":"彼女はピアニストとして認められた。","exampleEn":"She was recognized as a pianist."},{"id":"tosuru","kind":"pattern","tier":"morphological","labelJa":"～とする","labelEn":"try to / about to, suppose that, as a role","jlpt":"N2","gloss":"with volitional marks an attempt; with a noun phrase assigns a role or assumption","exampleJa":"家を出ようとしたとき、電話が鳴った。","exampleEn":"Just as I was about to leave, the phone rang."},{"id":"totan","kind":"pattern","tier":"lexical","labelJa":"～たとたん","labelEn":"the moment that","jlpt":"N3","gloss":"'just as / the instant that' — an unexpected event happens right after the first","exampleJa":"ドアを開けたとたん猫が逃げた。","exampleEn":"The moment I opened the door, the cat ran away."},{"id":"tsuide-ni","kind":"pattern","tier":"lexical","labelJa":"～ついでに","labelEn":"doing a second thing while you're at it","jlpt":"N3","gloss":"'on the same occasion as', doing a second thing while doing the first","exampleJa":"買い物のついでに郵便局へ行った。","exampleEn":"I went to the post office while I was out shopping."},{"id":"tsumori","kind":"pattern","tier":"lexical","labelJa":"～つもり","labelEn":"intend to / plan to","jlpt":"N4","gloss":"expresses the speaker's intention or plan","exampleJa":"来年日本に行くつもりです。","exampleEn":"I plan to go to Japan next year."},{"id":"tsutsu","kind":"pattern","tier":"morphological","labelJa":"～つつ","labelEn":"while doing (literary)","jlpt":"N1","gloss":"literary masu-stem connector marking two simultaneous actions or concession","exampleJa":"音楽を聴きつつ勉強する。","exampleEn":"I study while listening to music."},{"id":"tsutsu-aru","kind":"pattern","tier":"morphological","labelJa":"～つつある","labelEn":"in the process of changing","jlpt":"N1","gloss":"expresses an action or change progressing gradually toward completion","exampleJa":"景気は回復しつつある。","exampleEn":"The economy is gradually recovering."},{"id":"tsuzukeru","kind":"pattern","tier":"morphological","labelJa":"～続ける","labelEn":"keep doing / continue doing","jlpt":"N3","gloss":"compound-verb aspect: the action continues (V-ます-stem + 続ける)","exampleJa":"ずっと走り続ける。","exampleEn":"I keep running the whole time."},{"id":"tte","kind":"pattern","tier":"lexical","labelJa":"～って","labelEn":"casual \\"as for\\" and \\"they say\\"","jlpt":"N3","gloss":"casual topic marker or quoting particle","exampleJa":"田中さんって誰？","exampleEn":"Who is Tanaka?"},{"id":"uchi-ni","kind":"pattern","tier":"lexical","labelJa":"～うちに","labelEn":"while the condition still holds","jlpt":"N3","gloss":"'while the condition still holds' — do X before it changes (熱いうちに, 忘れないうちに)","exampleJa":"熱いうちに食べてください。","exampleEn":"Please eat it while it's hot."},{"id":"ue-de","kind":"pattern","tier":"lexical","labelJa":"～上で","labelEn":"after doing, and on that basis","jlpt":"N2","gloss":"'after doing X (and on that basis)' — X is a deliberate prerequisite for the next step (V-た上で)","exampleJa":"よく考えた上で決める。","exampleEn":"I'll decide after thinking it over carefully."},{"id":"uru-eru","kind":"pattern","tier":"morphological","labelJa":"～うる / ～える","labelEn":"can conceivably happen","jlpt":"N2","gloss":"literary potential suffix on masu-stem meaning can or could possibly happen","exampleJa":"それは十分にあり得る話だ。","exampleEn":"That's a perfectly conceivable story."},{"id":"volitional","kind":"conjugation","tier":"morphological","labelJa":"～う／よう","labelEn":"let's / I'll (volitional)","jlpt":"N4","gloss":null,"exampleJa":"一緒に昼ご飯を食べよう。","exampleEn":"Let's have lunch together.","category":"form"},{"id":"wake-da","kind":"pattern","tier":"lexical","labelJa":"～わけだ","labelEn":"so that's why, no wonder","jlpt":"N3","gloss":"draws a logical conclusion from what was just said — 'so that's why X'","exampleJa":"つまり疲れたわけだ。","exampleEn":"So that's why you're tired."},{"id":"wake-dewa-nai","kind":"pattern","tier":"lexical","labelJa":"～わけではない","labelEn":"it doesn't mean that / not necessarily","jlpt":"N3","gloss":"expresses partial or qualified negation of an assumption","exampleJa":"嫌いなわけではない。","exampleEn":"It's not that I dislike it."},{"id":"wake-ga-nai","kind":"pattern","tier":"lexical","labelJa":"～わけがない","labelEn":"there's no way / impossible","jlpt":"N3","gloss":"expresses the speaker's strong conviction that something cannot possibly be true","exampleJa":"彼が知らないわけがない。","exampleEn":"There's no way he doesn't know."},{"id":"wake-ni-wa-ikanai","kind":"pattern","tier":"lexical","labelJa":"～わけにはいかない","labelEn":"can't just / can't afford to","jlpt":"N3","gloss":"expresses inability due to social, moral, or external constraints, not physical ability","exampleJa":"今さらやめるわけにはいかない。","exampleEn":"I can't very well quit now."},{"id":"whether","kind":"pattern","tier":"lexical","labelJa":"～かどうか","labelEn":"whether or not","jlpt":"N4","gloss":"embeds a yes/no question into a larger sentence — 'whether (or not) X'","exampleJa":"行くかどうか分からない。","exampleEn":"I don't know whether or not I'll go."},{"id":"wo-komete","kind":"pattern","tier":"morphological","labelJa":"～を込めて","labelEn":"putting one's heart or feelings into an action","jlpt":"N2","gloss":"'putting (one's heart/feeling) into' an action (心を込めて, 愛を込めて)","exampleJa":"心を込めて作る。","exampleEn":"I make it with all my heart."},{"id":"wo-megutte","kind":"pattern","tier":"lexical","labelJa":"～をめぐって","labelEn":"over, revolving around an issue","jlpt":"N2","gloss":"a dispute, discussion, or contention revolves around the noun","exampleJa":"所有権をめぐって、二つの会社が争っている。","exampleEn":"Two companies are fighting over the ownership rights."},{"id":"wo-towazu","kind":"pattern","tier":"lexical","labelJa":"～を問わず","labelEn":"regardless of","jlpt":"N2","gloss":"the statement holds without regard to the preceding noun (age, gender, season …)","exampleJa":"年齢を問わず、誰でも参加できる。","exampleEn":"Anyone can participate, regardless of age."},{"id":"ya-inaya","kind":"pattern","tier":"lexical","labelJa":"～や否や","labelEn":"the instant that","jlpt":"N1","gloss":"the second action follows immediately upon the first (literary)","exampleJa":"ベルが鳴るや否や、生徒たちは教室を出た。","exampleEn":"The instant the bell rang, the students left the classroom."},{"id":"yasui","kind":"pattern","tier":"morphological","labelJa":"～やすい","labelEn":"easy to do","jlpt":"N4","gloss":"attaches to a verb masu-stem to say the action is easy to perform; the opposite of ～にくい","exampleJa":"この本は読みやすい。","exampleEn":"This book is easy to read."},{"id":"you-da","kind":"pattern","tier":"lexical","labelJa":"～ようだ","labelEn":"it seems / it looks like","jlpt":"N4","gloss":"expresses a subjective conjecture based on what the speaker observes or senses","exampleJa":"彼はもう帰ったようだ。","exampleEn":"It seems he has already gone home."},{"id":"you-ga-nai","kind":"pattern","tier":"lexical","labelJa":"～ようがない","labelEn":"no way to do it","jlpt":"N2","gloss":"indicates the speaker has no means to perform the action","exampleJa":"連絡先がないので連絡しようがない。","exampleEn":"I have no way to contact (him) since I don't have his info."},{"id":"you-ni-naru","kind":"pattern","tier":"lexical","labelJa":"～ようになる","labelEn":"come to do / become able to do","jlpt":"N4","gloss":"expresses a gradual change in state, ability, or habit","exampleJa":"日本語が話せるようになりました。","exampleEn":"I have become able to speak Japanese."},{"id":"you-ni-purpose","kind":"pattern","tier":"morphological","labelJa":"～ように","labelEn":"so that / in order to","jlpt":"N3","gloss":"purpose with a non-volitional/potential verb: 'so that (a state) comes about' (見えるように, 忘れないように)","exampleJa":"みんなに聞こえるように話す。","exampleEn":"I speak so that everyone can hear."},{"id":"you-ni-suru","kind":"pattern","tier":"lexical","labelJa":"～ようにする","labelEn":"make an effort to / make sure to","jlpt":"N4","gloss":"expresses a deliberate effort or habit to do something","exampleJa":"毎日運動するようにしています。","exampleEn":"I make sure to exercise every day."},{"id":"youna","kind":"pattern","tier":"lexical","labelJa":"～ような","labelEn":"\\"like\\" or \\"such as\\" before a noun","jlpt":"N3","gloss":"attributive 'like / as if', linking a noun-modifying simile (ような + noun)","exampleJa":"夢のような話だ。","exampleEn":"It's a dream-like story."},{"id":"zaru-wo-enai","kind":"pattern","tier":"lexical","labelJa":"～ざるを得ない","labelEn":"have no choice but to","jlpt":"N2","gloss":"'cannot help but / have no choice but to' — forced to do X (認めざるを得ない)","exampleJa":"事実を認めざるを得ない。","exampleEn":"I have no choice but to admit the facts."},{"id":"zu-ni-wa-irarenai","kind":"pattern","tier":"lexical","labelJa":"～ずにはいられない","labelEn":"can't help but do something","jlpt":"N2","gloss":"'can't help (doing) / can't keep from' — an irresistible urge (笑わずにはいられない)","exampleJa":"笑わずにはいられない。","exampleEn":"I can't help but laugh."},{"id":"zukume","kind":"pattern","tier":"morphological","labelJa":"～ずくめ","labelEn":"nothing but / full of","jlpt":"N1","gloss":"the situation consists entirely of the preceding noun (いいことずくめ)","exampleJa":"今年は贅沢ずくめの一年だった。","exampleEn":"This year was one of nothing but luxury."},{"id":"zuni","kind":"pattern","tier":"morphological","labelJa":"～ずに","labelEn":"without doing","jlpt":"N3","gloss":"negative manner 'without (doing)' — a more formal ～ないで (言わずに, せずに)","exampleJa":"何も言わずに出て行った。","exampleEn":"He left without saying anything."},{"id":"masen-ka","kind":"pattern","tier":"morphological","labelJa":"～ませんか","labelEn":"polite invitation (won't you?)","jlpt":"N5","gloss":"politely invites someone by asking a negative question","exampleJa":"一緒に映画を見ませんか。","exampleEn":"Won't you watch a movie with me?"},{"id":"mashou","kind":"pattern","tier":"morphological","labelJa":"～ましょう","labelEn":"let's (polite suggestion)","jlpt":"N5","gloss":"polite suggestion to do something together","exampleJa":"そろそろ帰りましょう。","exampleEn":"Let's head home soon."},{"id":"mashou-ka","kind":"pattern","tier":"morphological","labelJa":"～ましょうか","labelEn":"shall I? / shall we?","jlpt":"N5","gloss":"offers to do something for someone, or suggests doing it together","exampleJa":"荷物を持ちましょうか。","exampleEn":"Shall I carry your bag?"},{"id":"hoshii","kind":"pattern","tier":"lexical","labelJa":"～がほしい","labelEn":"wanting a thing","jlpt":"N5","gloss":"expresses wanting an object; for wanting to do something use ～たい","exampleJa":"新しいパソコンがほしい。","exampleEn":"I want a new computer."},{"id":"ni-iku","kind":"pattern","tier":"morphological","labelJa":"～に行く／～に来る（目的）","labelEn":"going or coming to do something (purpose)","jlpt":"N5","gloss":"verb stem + に + a movement verb: moving somewhere for a purpose","exampleJa":"友達と映画を見に行く。","exampleEn":"I'm going to see a movie with a friend."},{"id":"yori-hou-ga","kind":"pattern","tier":"lexical","labelJa":"～より～のほうが","labelEn":"comparing two things (more than)","jlpt":"N5","gloss":"compares two things: AよりBのほうが～ 'B is more … than A'","exampleJa":"電車より車のほうが速い。","exampleEn":"The car is faster than the train."},{"id":"ichiban","kind":"pattern","tier":"lexical","labelJa":"～の中で～が一番","labelEn":"the most within a group","jlpt":"N5","gloss":"picks the top item out of a group","exampleJa":"果物の中でりんごが一番好きだ。","exampleEn":"Of all fruits, I like apples the most."},{"id":"mada-te-inai","kind":"pattern","tier":"lexical","labelJa":"まだ～ていない","labelEn":"not yet","jlpt":"N5","gloss":"something hasn't happened yet (but is expected to)","exampleJa":"宿題はまだ終わっていない。","exampleEn":"I haven't finished my homework yet."},{"id":"ya-nado","kind":"pattern","tier":"lexical","labelJa":"～や～など","labelEn":"things like A and B (incomplete list)","jlpt":"N5","gloss":"lists some examples out of a larger set","exampleJa":"机の上に本やノートなどがある。","exampleEn":"There are books, notebooks and so on on the desk."},{"id":"to-omou","kind":"pattern","tier":"lexical","labelJa":"～と思う","labelEn":"I think that (opinion or guess)","jlpt":"N4","gloss":"gives the speaker's opinion or guess","exampleJa":"明日は雨が降ると思う。","exampleEn":"I think it will rain tomorrow."},{"id":"quote-to","kind":"pattern","tier":"lexical","labelJa":"～と言う／～と聞く","labelEn":"quoting what someone said","jlpt":"N4","gloss":"quotes what someone said or what one heard","exampleJa":"田中さんは明日来ると言っていた。","exampleEn":"Tanaka said he'd come tomorrow."},{"id":"made-ni","kind":"pattern","tier":"lexical","labelJa":"～までに","labelEn":"by (a deadline)","jlpt":"N4","gloss":"the latest point in time by which something happens; まで alone means 'until'","exampleJa":"五時までに帰ってきてね。","exampleEn":"Be back by five, okay?"},{"id":"nakute-mo-ii","kind":"pattern","tier":"morphological","labelJa":"～なくてもいい","labelEn":"you don't have to","jlpt":"N4","gloss":"says something isn't necessary","exampleJa":"明日は来なくてもいいよ。","exampleEn":"You don't have to come tomorrow."},{"id":"nasai","kind":"pattern","tier":"morphological","labelJa":"～なさい","labelEn":"do it! (instruction from above)","jlpt":"N4","gloss":"a command from a parent, teacher or superior; verb stem + なさい","exampleJa":"早く寝なさい。","exampleEn":"Go to bed already."},{"id":"you-to-omou","kind":"pattern","tier":"morphological","labelJa":"～（よ）うと思う","labelEn":"I'm thinking of doing","jlpt":"N4","gloss":"volitional form + と思う: a plan or intention","exampleJa":"来年、日本に行こうと思う。","exampleEn":"I'm thinking of going to Japan next year."},{"id":"yotei","kind":"pattern","tier":"lexical","labelJa":"～予定だ","labelEn":"it's planned / scheduled","jlpt":"N4","gloss":"something planned or arranged in advance","exampleJa":"来週、東京に行く予定だ。","exampleEn":"I'm scheduled to go to Tokyo next week."},{"id":"te-ageru","kind":"pattern","tier":"morphological","labelJa":"～てあげる","labelEn":"doing something for someone","jlpt":"N4","gloss":"the speaker (or someone) does a favor for another person","exampleJa":"弟に本を読んであげた。","exampleEn":"I read a book to my little brother."},{"id":"te-yaru","kind":"pattern","tier":"morphological","labelJa":"～てやる","labelEn":"doing for someone lower / I'll show you","jlpt":"N4","gloss":"does a favor for someone lower, or declares a determined (often aggressive) intention","exampleJa":"今度こそ勝ってやる！","exampleEn":"This time I'm going to win, just watch!"},{"id":"te-kudasaru","kind":"pattern","tier":"morphological","labelJa":"～てくださる","labelEn":"someone respected does something for me","jlpt":"N4","gloss":"honorific ～てくれる: a superior does a favor for the speaker","exampleJa":"先生が丁寧に説明してくださった。","exampleEn":"The teacher kindly explained it carefully."},{"id":"sasete-kudasai","kind":"pattern","tier":"morphological","labelJa":"～させてください","labelEn":"please let me do it","jlpt":"N4","gloss":"causative te-form + ください: asks permission to do something","exampleJa":"私にやらせてください。","exampleEn":"Please let me do it."},{"id":"you-ni-iu","kind":"pattern","tier":"lexical","labelJa":"～ように言う","labelEn":"telling someone to do something","jlpt":"N4","gloss":"reports an instruction or request: ～ように言う／頼む／注意する","exampleJa":"母に早く帰るように言われた。","exampleEn":"My mom told me to come home early."},{"id":"baai-wa","kind":"pattern","tier":"lexical","labelJa":"～場合は","labelEn":"in case of / if","jlpt":"N4","gloss":"a hypothetical or specific situation, often in rules and instructions","exampleJa":"雨の場合は、試合は中止です。","exampleEn":"In case of rain, the game is canceled."},{"id":"oki-ni","kind":"pattern","tier":"lexical","labelJa":"～おきに","labelEn":"every other / at intervals","jlpt":"N4","gloss":"repetition with a gap of a set amount of time or space","exampleJa":"薬は六時間おきに飲んでください。","exampleEn":"Take the medicine every six hours."},{"id":"zutsu","kind":"pattern","tier":"lexical","labelJa":"～ずつ","labelEn":"each / at a time","jlpt":"N4","gloss":"the same amount for each person, item or step","exampleJa":"一人二つずつ取ってください。","exampleEn":"Please take two each."},{"id":"kana","kind":"pattern","tier":"lexical","labelJa":"～かな","labelEn":"I wonder","jlpt":"N4","gloss":"the speaker wonders or is unsure; often talking to oneself","exampleJa":"明日は晴れるかな。","exampleEn":"I wonder if it'll be sunny tomorrow."},{"id":"ba-yokatta","kind":"pattern","tier":"morphological","labelJa":"～ばよかった","labelEn":"I should have","jlpt":"N4","gloss":"regret about something that didn't happen","exampleJa":"もっと早く来ればよかった。","exampleEn":"I should have come earlier."},{"id":"tara-dou","kind":"pattern","tier":"morphological","labelJa":"～たらどう","labelEn":"why don't you?","jlpt":"N4","gloss":"casual suggestion or advice","exampleJa":"少し休んだらどう？","exampleEn":"Why don't you take a little rest?"},{"id":"owaru","kind":"pattern","tier":"morphological","labelJa":"～終わる","labelEn":"finishing doing","jlpt":"N4","gloss":"verb stem + 終わる: completing an action","exampleJa":"その本、もう読み終わった？","exampleEn":"Have you finished reading that book?"},{"id":"te-yokatta","kind":"pattern","tier":"morphological","labelJa":"～てよかった","labelEn":"I'm glad that","jlpt":"N4","gloss":"relief or happiness about how something turned out","exampleJa":"会えてよかった。","exampleEn":"I'm glad I got to see you."},{"id":"question-ka","kind":"pattern","tier":"lexical","labelJa":"疑問詞＋か","labelEn":"question inside a sentence","jlpt":"N4","gloss":"a question inside a sentence: what / where / who … (I don't know, tell me, etc.)","exampleJa":"彼がどこに住んでいるか知らない。","exampleEn":"I don't know where he lives."},{"id":"tagaru","kind":"pattern","tier":"morphological","labelJa":"～たがる","labelEn":"someone else wants to","jlpt":"N4","gloss":"describes a third person's wish, which the speaker can only observe","exampleJa":"子供は外で遊びたがる。","exampleEn":"Kids always want to play outside."},{"id":"o-ni-naru","kind":"pattern","tier":"lexical","labelJa":"お～になる","labelEn":"honorific form of an action","jlpt":"N4","gloss":"respectful form for actions of a superior or customer: お + verb stem + になる","exampleJa":"社長はもうお帰りになりました。","exampleEn":"The president has already gone home."},{"id":"o-suru","kind":"pattern","tier":"lexical","labelJa":"お／ご～する","labelEn":"humble form of an action","jlpt":"N4","gloss":"humble form for the speaker's own actions toward others: お／ご + verb stem + する","exampleJa":"駅までお送りします。","exampleEn":"I'll take you to the station."},{"id":"sonkei-reru","kind":"pattern","tier":"morphological","labelJa":"～（ら）れる（尊敬）","labelEn":"honorific (looks like the passive)","jlpt":"N4","gloss":"the passive form used to show respect for the doer, not as a passive","exampleJa":"先生はもう帰られました。","exampleEn":"The teacher has already left."},{"id":"de-gozaimasu","kind":"pattern","tier":"lexical","labelJa":"～でございます","labelEn":"very polite form of です","jlpt":"N4","gloss":"very polite form of です, used by staff, butlers and in formal speech","exampleJa":"こちらがお部屋でございます。","exampleEn":"This is your room."},{"id":"ni-suru","kind":"pattern","tier":"lexical","labelJa":"～にする","labelEn":"deciding on / making it","jlpt":"N4","gloss":"noun + にする: choosing something, or making something into a state","exampleJa":"飲み物はコーヒーにします。","exampleEn":"I'll have coffee for my drink."},{"id":"demo-example","kind":"pattern","tier":"lexical","labelJa":"～でも","labelEn":"or something (soft example)","jlpt":"N4","gloss":"a soft, loose example or suggestion","exampleJa":"お茶でも飲みませんか。","exampleEn":"Would you like some tea or something?"},{"id":"toka","kind":"pattern","tier":"lexical","labelJa":"～とか","labelEn":"things like / I heard","jlpt":"N4","gloss":"lists vague examples (casual や); also passes on something heard","exampleJa":"週末は映画とか見る。","exampleEn":"On weekends I watch movies and stuff."},{"id":"ka-ka","kind":"pattern","tier":"lexical","labelJa":"～か～か","labelEn":"A or B / whether or not","jlpt":"N4","gloss":"presents alternatives, including 'whether or not'","exampleJa":"行くか行かないか、早く決めて。","exampleEn":"Decide quickly whether you're going or not."},{"id":"sore-ni","kind":"pattern","tier":"lexical","labelJa":"それに","labelEn":"besides / moreover","jlpt":"N4","gloss":"adds another point, usually a reason","exampleJa":"この店は安いし、それにおいしい。","exampleEn":"This place is cheap, and on top of that it's tasty."},{"id":"soretomo","kind":"pattern","tier":"lexical","labelJa":"それとも","labelEn":"or (in questions)","jlpt":"N4","gloss":"offers an alternative in a question","exampleJa":"コーヒーにする？それとも紅茶？","exampleEn":"Coffee? Or tea?"},{"id":"ba-ii","kind":"pattern","tier":"morphological","labelJa":"～ばいい／～たらいい","labelEn":"what you should do / all you have to do","jlpt":"N3","gloss":"gives advice, or asks what one should do","exampleJa":"分からなければ、先生に聞けばいい。","exampleEn":"If you don't understand, just ask the teacher."},{"id":"ba-ii-noni","kind":"pattern","tier":"morphological","labelJa":"～ばいいのに","labelEn":"I wish (if only)","jlpt":"N3","gloss":"the speaker wishes things were different","exampleJa":"雨がやめばいいのに。","exampleEn":"I wish the rain would stop."},{"id":"koto-wa-nai","kind":"pattern","tier":"lexical","labelJa":"～ことはない","labelEn":"there's no need to","jlpt":"N3","gloss":"says an action is unnecessary, often reassuringly","exampleJa":"そんなに心配することはないよ。","exampleEn":"There's no need to worry so much."},{"id":"koto-da","kind":"pattern","tier":"lexical","labelJa":"～ことだ","labelEn":"you should (firm advice)","jlpt":"N3","gloss":"firm advice about what is best to do","exampleJa":"上手になりたければ、毎日練習することだ。","exampleEn":"If you want to get better, practice every day."},{"id":"mono-reason","kind":"pattern","tier":"lexical","labelJa":"～もの／～もん","labelEn":"because (casual excuse)","jlpt":"N3","gloss":"a casual, often childish or emotional excuse at the end of a sentence","exampleJa":"だって、眠かったんだもん。","exampleEn":"But I was sleepy!"},{"id":"mono-dakara","kind":"pattern","tier":"lexical","labelJa":"～ものだから","labelEn":"because (explaining an excuse)","jlpt":"N3","gloss":"gives a reason that excuses the result","exampleJa":"道が混んでいたものだから、遅れてしまった。","exampleEn":"The roads were packed, so I ended up late."},{"id":"kke","kind":"pattern","tier":"lexical","labelJa":"～っけ","labelEn":"was it? (trying to remember)","jlpt":"N3","gloss":"asks about something the speaker has forgotten or wants to confirm","exampleJa":"あの人、名前何だっけ？","exampleEn":"What was that guy's name again?"},{"id":"kashira","kind":"pattern","tier":"lexical","labelJa":"～かしら","labelEn":"I wonder (feminine)","jlpt":"N3","gloss":"feminine version of ～かな","exampleJa":"彼、来るかしら。","exampleEn":"I wonder if he'll come."},{"id":"janai-ka","kind":"pattern","tier":"lexical","labelJa":"～じゃない（か）／～じゃん","labelEn":"isn't it? / see? (seeking agreement)","jlpt":"N3","gloss":"seeks agreement, points something out, or reproaches","exampleJa":"だから言ったじゃん！","exampleEn":"See, I told you!"},{"id":"datte","kind":"pattern","tier":"lexical","labelJa":"だって","labelEn":"but / because (protest)","jlpt":"N3","gloss":"casual protest or excuse at the start of a sentence; also 'even' after a noun","exampleJa":"だって、知らなかったんだもん。","exampleEn":"But I didn't know!"},{"id":"sae-ba","kind":"pattern","tier":"lexical","labelJa":"～さえ～ば","labelEn":"if only / as long as","jlpt":"N3","gloss":"a single condition is enough for the result","exampleJa":"お金さえあれば、何でもできる。","exampleEn":"As long as you have money, you can do anything."},{"id":"to-shitara","kind":"pattern","tier":"lexical","labelJa":"～としたら／～とすれば","labelEn":"supposing that / if","jlpt":"N3","gloss":"a hypothetical assumption","exampleJa":"宝くじが当たったとしたら、何を買う？","exampleEn":"Supposing you won the lottery, what would you buy?"},{"id":"tatoe-temo","kind":"pattern","tier":"lexical","labelJa":"たとえ～ても","labelEn":"even if (no matter what)","jlpt":"N3","gloss":"something holds no matter what happens","exampleJa":"たとえ雨が降っても、試合は行う。","exampleEn":"Even if it rains, the game will go ahead."},{"id":"masu-you-ni","kind":"pattern","tier":"lexical","labelJa":"～ますように","labelEn":"I hope / may it be (a wish)","jlpt":"N3","gloss":"a wish or prayer","exampleJa":"試験に合格できますように。","exampleEn":"I hope I pass the exam."},{"id":"rashii-typical","kind":"pattern","tier":"morphological","labelJa":"～らしい（典型）","labelEn":"typical of / just like a real","jlpt":"N3","gloss":"noun + らしい: having the ideal qualities of that thing","exampleJa":"今日は春らしい天気だ。","exampleEn":"Today's weather is very spring-like."},{"id":"teki","kind":"pattern","tier":"morphological","labelJa":"～的","labelEn":"of that nature (like English -ic or -al)","jlpt":"N3","gloss":"noun + 的: of that nature or from that point of view","exampleJa":"これは日本的な考え方だ。","exampleEn":"This is a very Japanese way of thinking."},{"id":"ni-kurabete","kind":"pattern","tier":"lexical","labelJa":"～に比べて","labelEn":"compared to","jlpt":"N3","gloss":"compares one thing with another","exampleJa":"去年に比べて、今年は暑い。","exampleEn":"This year is hotter than last year."},{"id":"ni-kawatte","kind":"pattern","tier":"lexical","labelJa":"～に代わって","labelEn":"in place of / on behalf of","jlpt":"N3","gloss":"someone or something acts instead of another","exampleJa":"部長に代わって、私がご説明します。","exampleEn":"I'll explain in place of the manager."},{"id":"ni-shitagatte","kind":"pattern","tier":"lexical","labelJa":"～に従って","labelEn":"as (one change follows another) / in accordance with","jlpt":"N3","gloss":"a change that follows another change, or following a rule","exampleJa":"年を取るに従って、体力が落ちる。","exampleEn":"As you get older, your stamina drops."},{"id":"toori","kind":"pattern","tier":"lexical","labelJa":"～とおり（に）","labelEn":"just as / exactly as","jlpt":"N3","gloss":"exactly as something says or was done","exampleJa":"説明書のとおりに組み立てた。","exampleEn":"I assembled it as the manual said."},{"id":"hodo-wa-nai","kind":"pattern","tier":"lexical","labelJa":"～ほど～はない","labelEn":"nothing compares to","jlpt":"N3","gloss":"says something is the most extreme of its kind","exampleJa":"家族ほど大切なものはない。","exampleEn":"Nothing is as important as family."},{"id":"te-tamaranai","kind":"pattern","tier":"morphological","labelJa":"～てたまらない","labelEn":"unbearably / dying to","jlpt":"N3","gloss":"a feeling so strong the speaker can't stand it","exampleJa":"暑くてたまらない。","exampleEn":"It's unbearably hot."},{"id":"te-shouganai","kind":"pattern","tier":"morphological","labelJa":"～てしょうがない／～て仕方がない","labelEn":"extremely / can't help feeling","jlpt":"N3","gloss":"a feeling or state the speaker can't control","exampleJa":"彼女に会いたくてしょうがない。","exampleEn":"I'm dying to see her."},{"id":"wari-ni","kind":"pattern","tier":"lexical","labelJa":"～わりに（は）","labelEn":"considering / for (unexpected for)","jlpt":"N3","gloss":"the result is different from what you'd expect","exampleJa":"この店は値段のわりにおいしい。","exampleEn":"This place is tasty for the price."},{"id":"nanka","kind":"pattern","tier":"lexical","labelJa":"～なんか","labelEn":"things like (dismissive)","jlpt":"N3","gloss":"casually gives an example, or belittles something","exampleJa":"宿題なんかやりたくない。","exampleEn":"I don't want to do stuff like homework."},{"id":"to-iu-yori","kind":"pattern","tier":"lexical","labelJa":"～というより","labelEn":"rather than","jlpt":"N3","gloss":"a more accurate description than the first one","exampleJa":"彼は友達というより家族だ。","exampleEn":"He's more family than a friend."},{"id":"to-iu-no-wa","kind":"pattern","tier":"lexical","labelJa":"～というのは","labelEn":"explaining what something means","jlpt":"N3","gloss":"defines or explains a word or situation","exampleJa":"「OK」というのは「大丈夫」という意味だ。","exampleEn":"'OK' means 'it's fine'."},{"id":"to-iu-koto-da","kind":"pattern","tier":"lexical","labelJa":"～ということだ","labelEn":"I hear that / that means","jlpt":"N3","gloss":"passes on information, or draws a conclusion","exampleJa":"来月から値段が上がるということだ。","exampleEn":"I hear prices are going up from next month."},{"id":"goto-ni","kind":"pattern","tier":"lexical","labelJa":"～ごとに","labelEn":"every / each (repeating per unit)","jlpt":"N3","gloss":"something repeats at each unit","exampleJa":"バスは十分ごとに来る。","exampleEn":"The bus comes every ten minutes."},{"id":"au","kind":"pattern","tier":"morphological","labelJa":"～合う","labelEn":"doing something to each other","jlpt":"N3","gloss":"verb stem + 合う: a mutual action","exampleJa":"二人は顔を見合って笑った。","exampleEn":"The two looked at each other and laughed."},{"id":"naosu","kind":"pattern","tier":"morphological","labelJa":"～直す","labelEn":"redoing something","jlpt":"N3","gloss":"verb stem + 直す: doing something again to fix it","exampleJa":"もう一度書き直してください。","exampleEn":"Please rewrite it once more."},{"id":"koto-instruction","kind":"pattern","tier":"lexical","labelJa":"～こと（指示）","labelEn":"rule or instruction (must / must not)","jlpt":"N3","gloss":"a written instruction or rule, ending a sentence with こと","exampleJa":"廊下を走らないこと。","exampleEn":"No running in the hallways."},{"id":"ni-mukete","kind":"pattern","tier":"lexical","labelJa":"～に向けて","labelEn":"toward / aimed at","jlpt":"N3","gloss":"a goal or target that efforts are directed to","exampleJa":"試験に向けて毎日勉強している。","exampleEn":"I'm studying every day for the exam."},{"id":"zu-ni-sumu","kind":"pattern","tier":"morphological","labelJa":"～ずに済む／～ないで済む","labelEn":"getting by without","jlpt":"N3","gloss":"avoiding something unpleasant or unnecessary","exampleJa":"雨がやんだので、傘を買わずに済んだ。","exampleEn":"The rain stopped, so I got by without buying an umbrella."},{"id":"te-goran","kind":"pattern","tier":"morphological","labelJa":"～てごらん","labelEn":"try it and see","jlpt":"N3","gloss":"gentle suggestion to try something, from parent or teacher","exampleJa":"ちょっと食べてごらん。","exampleEn":"Here, try a bite."},{"id":"sasete-itadaku","kind":"pattern","tier":"morphological","labelJa":"～させていただく","labelEn":"humbly doing (with permission)","jlpt":"N3","gloss":"very humble way to say the speaker will do something","exampleJa":"本日はお休みさせていただきます。","exampleEn":"We are closed today."},{"id":"sore-nanoni","kind":"pattern","tier":"lexical","labelJa":"それなのに／なのに","labelEn":"and yet / even so","jlpt":"N3","gloss":"a result that goes against expectations","exampleJa":"一生懸命勉強した。それなのに落ちた。","exampleEn":"I studied really hard. And yet I failed."},{"id":"suruto","kind":"pattern","tier":"lexical","labelJa":"すると","labelEn":"then / and at that moment","jlpt":"N3","gloss":"what happened right after an action","exampleJa":"ボタンを押した。すると、ドアが開いた。","exampleEn":"I pressed the button. Then the door opened."},{"id":"tsumari","kind":"pattern","tier":"lexical","labelJa":"つまり","labelEn":"in other words / so","jlpt":"N3","gloss":"restates or sums up what was said","exampleJa":"つまり、君は行かないということだね。","exampleEn":"So in other words, you're not going."},{"id":"nazenara","kind":"pattern","tier":"lexical","labelJa":"なぜなら（～から）","labelEn":"the reason is / because","jlpt":"N3","gloss":"gives the reason after the statement, usually ending in から","exampleJa":"今日は休む。なぜなら熱があるからだ。","exampleEn":"I'm taking today off. The reason is I have a fever."},{"id":"soredemo","kind":"pattern","tier":"lexical","labelJa":"それでも","labelEn":"even so / still","jlpt":"N3","gloss":"something holds despite what was just said","exampleJa":"何度も失敗した。それでも諦めない。","exampleEn":"I failed many times. Even so, I won't give up."},{"id":"sonoue","kind":"pattern","tier":"lexical","labelJa":"そのうえ","labelEn":"on top of that / in addition","jlpt":"N3","gloss":"adds a further point","exampleJa":"彼は頭がいい。そのうえ、スポーツも得意だ。","exampleEn":"He's smart. On top of that, he's good at sports."},{"id":"ta-tokoro","kind":"pattern","tier":"lexical","labelJa":"～たところ（結果）","labelEn":"when I did it, it turned out (result)","jlpt":"N2","gloss":"the outcome discovered after doing something","exampleJa":"先生に聞いてみたところ、すぐに答えてくれた。","exampleEn":"When I asked the teacher, she answered right away."},{"id":"ta-tokoro-de","kind":"pattern","tier":"lexical","labelJa":"～たところで","labelEn":"even if (it won't help)","jlpt":"N2","gloss":"even if you do it, it's pointless","exampleJa":"今から急いだところで、間に合わない。","exampleEn":"Even if we hurry now, we won't make it."},{"id":"tokoro-ni","kind":"pattern","tier":"lexical","labelJa":"～ところに／～ところへ","labelEn":"just as (at that moment)","jlpt":"N2","gloss":"something happens at the exact moment of another situation","exampleJa":"出かけようとしたところに、電話がかかってきた。","exampleEn":"Just as I was about to leave, the phone rang."},{"id":"mi-noun","kind":"pattern","tier":"morphological","labelJa":"～み","labelEn":"a felt quality (adjective to noun)","jlpt":"N2","gloss":"adjective stem + み: a quality you feel or sense","exampleJa":"このスープは甘みが強い。","exampleEn":"This soup is quite sweet."},{"id":"kara-ni-wa","kind":"pattern","tier":"lexical","labelJa":"～からには","labelEn":"now that / since (so must)","jlpt":"N2","gloss":"having done or decided something, you must follow through","exampleJa":"やると決めたからには、最後までやる。","exampleEn":"Now that I've decided to do it, I'll see it through."},{"id":"kara-shite","kind":"pattern","tier":"lexical","labelJa":"～からして","labelEn":"judging even from / starting with","jlpt":"N2","gloss":"even this one thing already shows it","exampleJa":"彼は話し方からして偉そうだ。","exampleEn":"Even the way he talks is arrogant."},{"id":"kara-to-itte","kind":"pattern","tier":"lexical","labelJa":"～からといって","labelEn":"just because (doesn't mean)","jlpt":"N2","gloss":"a reason doesn't automatically lead to the result","exampleJa":"高いからといって、いいものだとは限らない。","exampleEn":"Just because it's expensive doesn't mean it's good."},{"id":"kara-suru-to","kind":"pattern","tier":"lexical","labelJa":"～からすると／～から見ると","labelEn":"judging from / from the viewpoint of","jlpt":"N2","gloss":"a judgment based on a clue or a point of view","exampleJa":"彼の態度からすると、怒っているようだ。","exampleEn":"Judging from his attitude, he seems angry."},{"id":"ka-to-omou-to","kind":"pattern","tier":"lexical","labelJa":"～かと思うと／～かと思ったら","labelEn":"no sooner than / just when","jlpt":"N2","gloss":"one thing happens right after another, surprisingly","exampleJa":"泣いたかと思ったら、もう笑っている。","exampleEn":"No sooner had she cried than she was laughing again."},{"id":"ka-nai-ka-no-uchi-ni","kind":"pattern","tier":"lexical","labelJa":"～か～ないかのうちに","labelEn":"the moment / just as","jlpt":"N2","gloss":"the next action starts almost at the same time","exampleJa":"ベルが鳴るか鳴らないかのうちに、彼は教室を飛び出した。","exampleEn":"The moment the bell rang, he dashed out of the classroom."},{"id":"ni-kakete","kind":"pattern","tier":"lexical","labelJa":"～にかけて","labelEn":"over a span of time or place","jlpt":"N2","gloss":"a range of time or place: AからBにかけて","exampleJa":"夜から朝にかけて雨が降るでしょう。","exampleEn":"It will rain from tonight through the morning."},{"id":"ni-oujite","kind":"pattern","tier":"lexical","labelJa":"～に応じて","labelEn":"according to / in response to","jlpt":"N2","gloss":"changes to match a situation or request","exampleJa":"収入に応じて税金が決まる。","exampleEn":"Taxes are set according to income."},{"id":"ni-sotte","kind":"pattern","tier":"lexical","labelJa":"～に沿って","labelEn":"along / in line with","jlpt":"N2","gloss":"following a path, plan or wishes","exampleJa":"川に沿って歩いた。","exampleEn":"I walked along the river."},{"id":"wo-chuushin-ni","kind":"pattern","tier":"lexical","labelJa":"～を中心に","labelEn":"centered on / mainly","jlpt":"N2","gloss":"something is the focus or center","exampleJa":"このサークルは学生を中心に活動している。","exampleEn":"This club is made up mainly of students."},{"id":"wo-moto-ni","kind":"pattern","tier":"lexical","labelJa":"～をもとに","labelEn":"based on","jlpt":"N2","gloss":"something is used as the source or basis","exampleJa":"実際の事件をもとに映画が作られた。","exampleEn":"The movie was made based on a real incident."},{"id":"wo-tsuujite","kind":"pattern","tier":"lexical","labelJa":"～を通じて／～を通して","labelEn":"through / via / throughout","jlpt":"N2","gloss":"a means or channel; also 'throughout' a period","exampleJa":"友達を通じて彼と知り合った。","exampleEn":"I got to know him through a friend."},{"id":"wo-kikkake-ni","kind":"pattern","tier":"lexical","labelJa":"～をきっかけに","labelEn":"triggered by / taking the opportunity of","jlpt":"N2","gloss":"an event that started something","exampleJa":"留学をきっかけに、日本に興味を持った。","exampleEn":"Studying abroad got me interested in Japan."},{"id":"wo-hajime","kind":"pattern","tier":"lexical","labelJa":"～をはじめ","labelEn":"starting with / including","jlpt":"N2","gloss":"names the main example out of many","exampleJa":"東京をはじめ、全国で雨が降った。","exampleEn":"It rained all over the country, Tokyo included."},{"id":"ni-hanshite","kind":"pattern","tier":"lexical","labelJa":"～に反して","labelEn":"contrary to / against","jlpt":"N2","gloss":"the result goes against expectations or rules","exampleJa":"予想に反して、試合に負けた。","exampleEn":"Contrary to expectations, we lost the game."},{"id":"ni-tomonatte","kind":"pattern","tier":"lexical","labelJa":"～に伴って","labelEn":"along with / as (one change brings another)","jlpt":"N2","gloss":"one change goes together with another","exampleJa":"人口の増加に伴って、問題も増えた。","exampleEn":"As the population grew, so did the problems."},{"id":"to-tomo-ni","kind":"pattern","tier":"lexical","labelJa":"～とともに","labelEn":"together with / along with","jlpt":"N2","gloss":"together with someone, or a change happening alongside another","exampleJa":"時代とともに言葉も変わる。","exampleEn":"Language changes with the times."},{"id":"ni-watatte","kind":"pattern","tier":"lexical","labelJa":"～にわたって","labelEn":"over / throughout (a whole span)","jlpt":"N2","gloss":"covers a whole span of time or area","exampleJa":"会議は三日間にわたって行われた。","exampleEn":"The conference was held over three days."},{"id":"ni-saishite","kind":"pattern","tier":"lexical","labelJa":"～に際して","labelEn":"on the occasion of / when","jlpt":"N2","gloss":"at the time of a special event (formal)","exampleJa":"出発に際して、注意事項を説明します。","exampleEn":"Before departure, I will explain the precautions."},{"id":"ni-sakidatte","kind":"pattern","tier":"lexical","labelJa":"～に先立って","labelEn":"prior to / before","jlpt":"N2","gloss":"something done in preparation before an event","exampleJa":"試合に先立って、開会式が行われた。","exampleEn":"An opening ceremony was held before the game."},{"id":"ni-kagitte","kind":"pattern","tier":"lexical","labelJa":"～に限って","labelEn":"of all times / only (when)","jlpt":"N2","gloss":"something bad happens exactly when it shouldn't, or a trusted person wouldn't do it","exampleJa":"急いでいる時に限って、電車が遅れる。","exampleEn":"The train is always late exactly when I'm in a hurry."},{"id":"ni-kagiru","kind":"pattern","tier":"lexical","labelJa":"～に限る","labelEn":"nothing beats / it's best to","jlpt":"N2","gloss":"the speaker thinks this is the best option","exampleJa":"疲れた時は寝るに限る。","exampleEn":"When you're tired, nothing beats sleep."},{"id":"ni-kakawarazu","kind":"pattern","tier":"lexical","labelJa":"～にかかわらず","labelEn":"regardless of","jlpt":"N2","gloss":"something doesn't depend on a factor (unlike にもかかわらず 'despite')","exampleJa":"年齢にかかわらず、誰でも参加できる。","exampleEn":"Anyone can join, regardless of age."},{"id":"ni-hoka-naranai","kind":"pattern","tier":"lexical","labelJa":"～にほかならない","labelEn":"is nothing other than","jlpt":"N2","gloss":"strongly asserts what something really is","exampleJa":"成功は努力の結果にほかならない。","exampleEn":"Success is nothing but the result of effort."},{"id":"osore-ga-aru","kind":"pattern","tier":"lexical","labelJa":"～おそれがある","labelEn":"there's a risk that","jlpt":"N2","gloss":"warns of a possible bad outcome (news, forecasts)","exampleJa":"台風が上陸するおそれがある。","exampleEn":"There is a risk that the typhoon will make landfall."},{"id":"gimi","kind":"pattern","tier":"morphological","labelJa":"～気味","labelEn":"a bit / slightly (a tendency)","jlpt":"N2","gloss":"a slight tendency or sign of something (usually bad)","exampleJa":"最近、少し太り気味だ。","exampleEn":"Lately I've been putting on a bit of weight."},{"id":"muke","kind":"pattern","tier":"morphological","labelJa":"～向け／～向き","labelEn":"aimed at / suitable for","jlpt":"N2","gloss":"向け: made for a target group; 向き: suited to","exampleJa":"これは子供向けの本だ。","exampleEn":"This is a book for children."},{"id":"nuku","kind":"pattern","tier":"morphological","labelJa":"～抜く","labelEn":"doing to the very end","jlpt":"N2","gloss":"verb stem + 抜く: doing something completely, despite difficulty","exampleJa":"最後まで走り抜いた。","exampleEn":"I ran all the way to the end."},{"id":"kkonai","kind":"pattern","tier":"morphological","labelJa":"～っこない","labelEn":"there's no way (casual)","jlpt":"N2","gloss":"verb stem + っこない: something absolutely can't happen (casual)","exampleJa":"そんなこと、できっこない。","exampleEn":"There's no way I can do that."},{"id":"mai","kind":"pattern","tier":"morphological","labelJa":"～まい","labelEn":"will not / probably not","jlpt":"N2","gloss":"a strong negative intention, or a negative guess","exampleJa":"二度とあの店には行くまい。","exampleEn":"I'll never go to that place again."},{"id":"you-dewanaika","kind":"pattern","tier":"morphological","labelJa":"～（よ）うではないか","labelEn":"let's (rallying call)","jlpt":"N2","gloss":"volitional form + ではないか: calls on others to act together","exampleJa":"みんなで力を合わせようではないか。","exampleEn":"Let's all join forces!"},{"id":"koto-ni-feel","kind":"pattern","tier":"lexical","labelJa":"～ことに（は）","labelEn":"emphasizing a feeling (to my surprise)","jlpt":"N2","gloss":"emotion word + ことに: emphasizes the speaker's feeling","exampleJa":"驚いたことに、彼は一人で全部やった。","exampleEn":"To my surprise, he did it all by himself."},{"id":"koto-kara","kind":"pattern","tier":"lexical","labelJa":"～ことから","labelEn":"from the fact that","jlpt":"N2","gloss":"gives the basis for a conclusion or a name","exampleJa":"顔が似ていることから、兄弟だと分かった。","exampleEn":"From how alike they looked, I could tell they were brothers."},{"id":"koto-ka","kind":"pattern","tier":"lexical","labelJa":"～ことか","labelEn":"how very (exclamation)","jlpt":"N2","gloss":"an exclamation of strong feeling, often with どれほど／何度","exampleJa":"どれほど心配したことか。","exampleEn":"You have no idea how worried I was!"},{"id":"koto-naku","kind":"pattern","tier":"lexical","labelJa":"～ことなく","labelEn":"without (ever) doing","jlpt":"N2","gloss":"an action continues without something happening","exampleJa":"彼は休むことなく働き続けた。","exampleEn":"He kept working without a single break."},{"id":"koto-wa-ga","kind":"pattern","tier":"lexical","labelJa":"～ことは～が","labelEn":"it's true that, but","jlpt":"N2","gloss":"admits something but adds a reservation","exampleJa":"読んだことは読んだが、よく分からなかった。","exampleEn":"I did read it, but I didn't really understand it."},{"id":"koto-dakara","kind":"pattern","tier":"lexical","labelJa":"～ことだから","labelEn":"knowing (someone), surely","jlpt":"N2","gloss":"a judgment based on what someone is like","exampleJa":"真面目な彼のことだから、きっと来るだろう。","exampleEn":"Knowing how serious he is, he'll surely come."},{"id":"mono-ka","kind":"pattern","tier":"lexical","labelJa":"～ものか／～もんか","labelEn":"no way (strong denial)","jlpt":"N2","gloss":"a strong, emotional denial","exampleJa":"あんな店、二度と行くもんか。","exampleEn":"No way I'm ever going to that place again."},{"id":"mono-nara","kind":"pattern","tier":"lexical","labelJa":"～ものなら","labelEn":"if (I) could / if you dare","jlpt":"N2","gloss":"a wish that's hard to fulfill, or a warning (volitional + ものなら)","exampleJa":"できるものなら、もう一度やり直したい。","exampleEn":"If only I could, I'd do it all over again."},{"id":"mono-ga-aru","kind":"pattern","tier":"lexical","labelJa":"～ものがある","labelEn":"there's something (about it)","jlpt":"N2","gloss":"the speaker senses a certain quality","exampleJa":"彼の演奏には人を感動させるものがある。","exampleEn":"There's something deeply moving about his playing."},{"id":"to-iu-mono-dewa-nai","kind":"pattern","tier":"lexical","labelJa":"～というものではない","labelEn":"it's not (simply) the case that","jlpt":"N2","gloss":"rejects an overly simple view","exampleJa":"お金さえあればいいというものではない。","exampleEn":"It's not as if money is all you need."},{"id":"te-naranai","kind":"pattern","tier":"morphological","labelJa":"～てならない","labelEn":"can't help feeling","jlpt":"N2","gloss":"a feeling that arises naturally and strongly","exampleJa":"将来が不安でならない。","exampleEn":"I can't help being anxious about the future."},{"id":"te-kara-denai-to","kind":"pattern","tier":"morphological","labelJa":"～てからでないと","labelEn":"not until / only after (first)","jlpt":"N2","gloss":"something is only possible after something else","exampleJa":"親と相談してからでないと決められない。","exampleEn":"I can't decide until I've talked with my parents."},{"id":"te-irai","kind":"pattern","tier":"morphological","labelJa":"～て以来","labelEn":"ever since","jlpt":"N2","gloss":"a state that has continued since a past event","exampleJa":"日本に来て以来、ずっと東京に住んでいる。","exampleEn":"Ever since I came to Japan, I've lived in Tokyo."},{"id":"te-hajimete","kind":"pattern","tier":"morphological","labelJa":"～てはじめて","labelEn":"only after (did I realize)","jlpt":"N2","gloss":"a realization that only comes after an experience","exampleJa":"病気になってはじめて健康の大切さが分かった。","exampleEn":"Only after I got sick did I understand how important health is."},{"id":"nai-koto-wa-nai","kind":"pattern","tier":"lexical","labelJa":"～ないことはない","labelEn":"it's not that (I) can't / not impossible","jlpt":"N2","gloss":"a weak, reluctant yes","exampleJa":"難しいが、できないことはない。","exampleEn":"It's hard, but not impossible."},{"id":"nai-koto-ni-wa","kind":"pattern","tier":"lexical","labelJa":"～ないことには","labelEn":"unless (first)","jlpt":"N2","gloss":"nothing can happen until a condition is met","exampleJa":"実際に見ないことには、何とも言えない。","exampleEn":"I can't say anything until I actually see it."},{"id":"kagiri-condition","kind":"pattern","tier":"lexical","labelJa":"～限り（は）／～ない限り","labelEn":"as long as / unless","jlpt":"N2","gloss":"a condition that holds for as long as the situation lasts; with ない: 'unless'","exampleJa":"諦めない限り、チャンスはある。","exampleEn":"As long as you don't give up, there's a chance."},{"id":"dake-atte","kind":"pattern","tier":"lexical","labelJa":"～だけあって","labelEn":"as you'd expect from","jlpt":"N2","gloss":"the result matches someone's ability or effort","exampleJa":"十年も住んでいただけあって、彼は町に詳しい。","exampleEn":"As you'd expect after ten years there, he knows the town well."},{"id":"dake-ni","kind":"pattern","tier":"lexical","labelJa":"～だけに","labelEn":"precisely because","jlpt":"N2","gloss":"the result is all the stronger because of a fact","exampleJa":"期待していただけに、がっかりした。","exampleEn":"Precisely because I had high hopes, I was disappointed."},{"id":"bakarika","kind":"pattern","tier":"lexical","labelJa":"～ばかりか","labelEn":"not only (but even)","jlpt":"N2","gloss":"adds something even more surprising","exampleJa":"彼は謝らないばかりか、文句まで言った。","exampleEn":"Not only did he not apologize, he even complained."},{"id":"hoka-nai","kind":"pattern","tier":"lexical","labelJa":"～ほかない／～よりほかない","labelEn":"have no choice but to","jlpt":"N2","gloss":"there is no other option","exampleJa":"電車がないので、歩くほかない。","exampleEn":"There are no trains, so I have no choice but to walk."},{"id":"to-ieba","kind":"pattern","tier":"lexical","labelJa":"～といえば／～というと","labelEn":"speaking of / when it comes to","jlpt":"N2","gloss":"brings up a topic, or the first thing that comes to mind","exampleJa":"日本といえば、富士山だ。","exampleEn":"When you think of Japan, you think of Mt. Fuji."},{"id":"ue-ni","kind":"pattern","tier":"lexical","labelJa":"～上に","labelEn":"besides / not only that","jlpt":"N2","gloss":"adds a further (usually similar) point","exampleJa":"この部屋は狭い上に、家賃が高い。","exampleEn":"This room is small, and on top of that the rent is high."},{"id":"ni-seyo","kind":"pattern","tier":"lexical","labelJa":"～にせよ／～にしろ","labelEn":"whether or not / even if","jlpt":"N2","gloss":"regardless of which option or situation","exampleJa":"行くにせよ行かないにせよ、連絡してください。","exampleEn":"Whether you go or not, let me know."},{"id":"to-shitemo","kind":"pattern","tier":"lexical","labelJa":"～としても","labelEn":"even if (supposing)","jlpt":"N2","gloss":"even assuming something, the result stays the same","exampleJa":"失敗したとしても、後悔しない。","exampleEn":"Even if I fail, I won't regret it."},{"id":"wa-tomokaku","kind":"pattern","tier":"lexical","labelJa":"～はともかく","labelEn":"setting aside / regardless of","jlpt":"N2","gloss":"puts one point aside to focus on another","exampleJa":"見た目はともかく、味はいい。","exampleEn":"Looks aside, it tastes good."},{"id":"wa-mochiron","kind":"pattern","tier":"lexical","labelJa":"～はもちろん／～はもとより","labelEn":"not to mention / of course","jlpt":"N2","gloss":"something obvious is included, and so is more","exampleJa":"彼は英語はもちろん、中国語も話せる。","exampleEn":"He speaks Chinese, not to mention English."},{"id":"buri","kind":"pattern","tier":"morphological","labelJa":"～ぶり","labelEn":"for the first time in / way of doing","jlpt":"N2","gloss":"time + ぶり: first time after a gap; noun + ぶり: the way something is done","exampleJa":"三年ぶりに故郷に帰った。","exampleEn":"I went back to my hometown for the first time in three years."},{"id":"kurai-nara","kind":"pattern","tier":"lexical","labelJa":"～くらいなら","labelEn":"rather than (I'd prefer)","jlpt":"N2","gloss":"the speaker would prefer anything to the first option","exampleJa":"謝るくらいなら、最初からするな。","exampleEn":"If you're going to apologize, don't do it in the first place."},{"id":"mo-ba-mo","kind":"pattern","tier":"lexical","labelJa":"～も～ば～も","labelEn":"both A and B","jlpt":"N2","gloss":"lists two (often contrasting) things","exampleJa":"彼は歌も歌えばダンスもする。","exampleEn":"He both sings and dances."},{"id":"yara-yara","kind":"pattern","tier":"lexical","labelJa":"～やら～やら","labelEn":"what with A and B","jlpt":"N2","gloss":"lists examples, often of a chaotic situation","exampleJa":"掃除やら洗濯やらで忙しかった。","exampleEn":"What with cleaning and laundry, I was busy."},{"id":"to-wa-kagiranai","kind":"pattern","tier":"lexical","labelJa":"～とは限らない","labelEn":"not necessarily","jlpt":"N2","gloss":"something isn't always true","exampleJa":"高いものがいいものだとは限らない。","exampleEn":"Expensive things aren't necessarily good."},{"id":"sura","kind":"pattern","tier":"lexical","labelJa":"～すら","labelEn":"even (formal emphasis)","jlpt":"N1","gloss":"emphasizes an extreme example (formal さえ)","exampleJa":"忙しくて、寝る時間すらない。","exampleEn":"I'm so busy I don't even have time to sleep."},{"id":"nomi-narazu","kind":"pattern","tier":"lexical","labelJa":"～のみならず","labelEn":"not only (formal)","jlpt":"N1","gloss":"formal ～だけでなく","exampleJa":"彼は国内のみならず、海外でも有名だ。","exampleEn":"He's famous not only at home but also abroad."},{"id":"ni-koshita-koto-wa-nai","kind":"pattern","tier":"lexical","labelJa":"～に越したことはない","labelEn":"it's best if / nothing is better than","jlpt":"N1","gloss":"it's best if something is the case","exampleJa":"早く治るに越したことはない。","exampleEn":"The sooner it heals, the better."},{"id":"made-mo-nai","kind":"pattern","tier":"lexical","labelJa":"～までもない","labelEn":"there's no need to (it's obvious)","jlpt":"N1","gloss":"something is too obvious to need doing or saying","exampleJa":"言うまでもなく、健康は大切だ。","exampleEn":"Needless to say, health is important."},{"id":"made-da","kind":"pattern","tier":"lexical","labelJa":"～までだ","labelEn":"will simply (if it comes to it) / just","jlpt":"N1","gloss":"if it comes to it, the speaker will simply do this; or 'just did it, nothing more'","exampleJa":"だめなら、もう一度やるまでだ。","exampleEn":"If it doesn't work, I'll just do it again."},{"id":"shimatsu","kind":"pattern","tier":"lexical","labelJa":"～始末だ","labelEn":"ending up in a sorry state","jlpt":"N1","gloss":"a bad outcome after a string of problems","exampleJa":"遅刻した上に、宿題まで忘れる始末だ。","exampleEn":"He was late, and then even forgot his homework."},{"id":"kiwamari-nai","kind":"pattern","tier":"lexical","labelJa":"～極まりない／～極まる","labelEn":"extremely (to the limit)","jlpt":"N1","gloss":"the most extreme degree (usually negative)","exampleJa":"彼の態度は失礼極まりない。","exampleEn":"His attitude is extremely rude."},{"id":"kagiri-da","kind":"pattern","tier":"lexical","labelJa":"～限りだ","labelEn":"feeling extremely (happy, lonely)","jlpt":"N1","gloss":"the speaker feels something to the utmost","exampleJa":"一人で寂しい限りだ。","exampleEn":"Being alone, I feel so lonely."},{"id":"wa-oroka","kind":"pattern","tier":"lexical","labelJa":"～はおろか","labelEn":"let alone / not to mention","jlpt":"N1","gloss":"not even the easier thing, let alone the harder one","exampleJa":"漢字はおろか、ひらがなも読めない。","exampleEn":"He can't read hiragana, let alone kanji."},{"id":"mo-sarukoto-nagara","kind":"pattern","tier":"lexical","labelJa":"～もさることながら","labelEn":"not only (but even more so)","jlpt":"N1","gloss":"acknowledges one point and stresses another","exampleJa":"味もさることながら、店の雰囲気もいい。","exampleEn":"The food is great, and the atmosphere even more so."},{"id":"wa-sateoki","kind":"pattern","tier":"lexical","labelJa":"～はさておき","labelEn":"setting aside (moving to the main point)","jlpt":"N1","gloss":"drops one topic to move to the main one","exampleJa":"冗談はさておき、本題に入ろう。","exampleEn":"Jokes aside, let's get down to business."},{"id":"te-yamanai","kind":"pattern","tier":"morphological","labelJa":"～てやまない","labelEn":"never stop (hoping / loving)","jlpt":"N1","gloss":"a deep, lasting feeling (formal)","exampleJa":"皆様のご活躍を願ってやみません。","exampleEn":"I sincerely wish you all the best."},{"id":"you-ga","kind":"pattern","tier":"morphological","labelJa":"～（よ）うが／～（よ）うと","labelEn":"no matter what / however much","jlpt":"N1","gloss":"volitional form + が／と: nothing changes the outcome","exampleJa":"誰が何と言おうと、私は行く。","exampleEn":"No matter what anyone says, I'm going."},{"id":"wo-motte","kind":"pattern","tier":"lexical","labelJa":"～をもって","labelEn":"as of / by means of (formal)","jlpt":"N1","gloss":"formal: a point in time, or the means used","exampleJa":"本日をもって閉店いたします。","exampleEn":"We are closing as of today."},{"id":"ga-saigo","kind":"pattern","tier":"lexical","labelJa":"～が最後","labelEn":"once (it happens), there's no stopping","jlpt":"N1","gloss":"once something happens, the result is inevitable","exampleJa":"彼は寝たが最後、朝まで起きない。","exampleEn":"Once he falls asleep, he won't wake until morning."},{"id":"to-omoikiya","kind":"pattern","tier":"lexical","labelJa":"～と思いきや","labelEn":"just when I thought (but actually)","jlpt":"N1","gloss":"the result was the opposite of what was expected","exampleJa":"晴れると思いきや、急に雨が降り出した。","exampleEn":"Just when I thought it'd be sunny, it suddenly started raining."},{"id":"dewa-arumaishi","kind":"pattern","tier":"lexical","labelJa":"～ではあるまいし","labelEn":"it's not as if","jlpt":"N1","gloss":"it's not as if X is the case, so act accordingly","exampleJa":"子供じゃあるまいし、自分でやりなさい。","exampleEn":"You're not a kid, do it yourself."},{"id":"te-kara-to-iu-mono","kind":"pattern","tier":"morphological","labelJa":"～てからというもの","labelEn":"ever since (a big change)","jlpt":"N1","gloss":"a big change that has continued since an event","exampleJa":"彼女に会ってからというもの、毎日が楽しい。","exampleEn":"Ever since I met her, every day has been fun."},{"id":"zujimai","kind":"pattern","tier":"morphological","labelJa":"～ずじまい","labelEn":"ended up never doing","jlpt":"N1","gloss":"something meant to happen never happened","exampleJa":"結局、彼には会えずじまいだった。","exampleEn":"In the end, I never got to see him."},{"id":"to-iedomo","kind":"pattern","tier":"lexical","labelJa":"～といえども","labelEn":"even though / even if (formal)","jlpt":"N1","gloss":"even granting something, the conclusion holds","exampleJa":"子供といえども、ルールは守らなければならない。","exampleEn":"Even children have to follow the rules."},{"id":"to-ittara-nai","kind":"pattern","tier":"lexical","labelJa":"～といったらない","labelEn":"indescribably / extremely","jlpt":"N1","gloss":"so extreme it can't be put into words","exampleJa":"あの時の恥ずかしさといったらない。","exampleEn":"I can't describe how embarrassing that was."},{"id":"naradewa","kind":"pattern","tier":"lexical","labelJa":"～ならでは","labelEn":"only possible with / unique to","jlpt":"N1","gloss":"something only possible with this person or place","exampleJa":"これは京都ならではの景色だ。","exampleEn":"This is scenery you can only find in Kyoto."},{"id":"nbakari","kind":"pattern","tier":"morphological","labelJa":"～んばかり","labelEn":"as if about to","jlpt":"N1","gloss":"nai-stem + んばかり: so close to doing it","exampleJa":"彼女は泣き出さんばかりの顔をしていた。","exampleEn":"She looked as if she was about to burst into tears."},{"id":"to-bakari-ni","kind":"pattern","tier":"lexical","labelJa":"～とばかりに","labelEn":"as if to say","jlpt":"N1","gloss":"acting as though saying something","exampleJa":"彼は「待ってました」とばかりに立ち上がった。","exampleEn":"He stood up as if to say 'I've been waiting for this.'"},{"id":"katawara","kind":"pattern","tier":"lexical","labelJa":"～かたわら","labelEn":"while also (doing on the side)","jlpt":"N1","gloss":"a side activity alongside one's main work","exampleJa":"彼は会社で働くかたわら、小説を書いている。","exampleEn":"While working at a company, he also writes novels."},{"id":"gatera","kind":"pattern","tier":"lexical","labelJa":"～がてら","labelEn":"while (combining two purposes)","jlpt":"N1","gloss":"doing something along the way while doing something else","exampleJa":"散歩がてら、パンを買いに行った。","exampleEn":"I went to buy bread while out for a walk."},{"id":"nari-ni","kind":"pattern","tier":"lexical","labelJa":"～なりに","labelEn":"in one's own way","jlpt":"N1","gloss":"within one's own abilities or situation","exampleJa":"私なりに頑張ってみた。","exampleEn":"I tried my best in my own way."},{"id":"gotoku","kind":"pattern","tier":"lexical","labelJa":"～ごとく／～ごとき","labelEn":"like / as if (literary)","jlpt":"N1","gloss":"literary comparison (～ように)","exampleJa":"彼は風のごとく走り去った。","exampleEn":"He ran off like the wind."},{"id":"mamire","kind":"pattern","tier":"morphological","labelJa":"～まみれ","labelEn":"covered in (something messy)","jlpt":"N1","gloss":"completely covered in something dirty or unpleasant","exampleJa":"子供たちは泥まみれになって遊んだ。","exampleEn":"The kids played until they were covered in mud."},{"id":"soba-kara","kind":"pattern","tier":"lexical","labelJa":"～そばから","labelEn":"as soon as (again and again)","jlpt":"N1","gloss":"something is undone right after it happens, over and over","exampleJa":"覚えるそばから忘れてしまう。","exampleEn":"I forget things as soon as I learn them."},{"id":"wo-yogi-naku","kind":"pattern","tier":"lexical","labelJa":"～を余儀なくされる","labelEn":"being forced to","jlpt":"N1","gloss":"circumstances leave no other choice","exampleJa":"大雨のため、試合は中止を余儀なくされた。","exampleEn":"Because of the heavy rain, the game had to be canceled."},{"id":"wo-yoso-ni","kind":"pattern","tier":"lexical","labelJa":"～をよそに","labelEn":"ignoring / in spite of","jlpt":"N1","gloss":"acting without regard for others’ feelings or circumstances","exampleJa":"親の心配をよそに、彼は一人で旅に出た。","exampleEn":"Ignoring his parents’ worries, he set off on a trip alone."},{"id":"tari-tomo","kind":"pattern","tier":"lexical","labelJa":"～たりとも","labelEn":"not even (a single)","jlpt":"N1","gloss":"one + counter + たりとも: not even the smallest amount","exampleJa":"一円たりとも無駄にできない。","exampleEn":"I can't waste even a single yen."},{"id":"de-are","kind":"pattern","tier":"lexical","labelJa":"～であれ","labelEn":"whatever / whether (it is)","jlpt":"N1","gloss":"no matter what something is","exampleJa":"理由が何であれ、暴力は許されない。","exampleEn":"Whatever the reason, violence is unacceptable."},{"id":"nu","kind":"pattern","tier":"morphological","labelJa":"～ぬ","labelEn":"literary negative (= ない)","jlpt":"N1","gloss":"classical negative ending, = ない (also in set phrases and period dramas)","exampleJa":"知らぬ間に眠ってしまった。","exampleEn":"I fell asleep without realizing it."},{"id":"bekarazu","kind":"pattern","tier":"lexical","labelJa":"～べからず","labelEn":"must not (on signs)","jlpt":"N1","gloss":"a strong prohibition, often on signs","exampleJa":"芝生に入るべからず。","exampleEn":"Keep off the grass."},{"id":"ue-wa","kind":"pattern","tier":"lexical","labelJa":"～上は","labelEn":"now that (I've committed)","jlpt":"N1","gloss":"having taken on something, one must see it through","exampleJa":"引き受けた上は、最後まで責任を持つ。","exampleEn":"Now that I've taken it on, I'll take responsibility to the end."}]`);export{e as default};
